export enum AttendanceType {
  Worship = '예배',
  Gathering = '집회',
  Wool = '울모임'
}

export interface Member {
  id: string;
  name: string;
  group: string; // 소그룹
  wool: string; // 울
  prayerRequest?: string;
  specialNotes?: string;
}

export interface AttendanceRecord {
  id: string;
  memberId: string;
  date: string; // YYYY-MM-DD
  types: AttendanceType[]; // A member can attend multiple types on one day
}

export interface JoinedRecord extends Member {
  attendanceDate?: string;
  attendanceTypes?: AttendanceType[];
}

export interface WeeklyStats {
  date: string;
  worshipCount: number;
  gatheringCount: number;
  woolCount: number;
}

export interface GroupStats {
  groupName: string;
  totalWorship: number;
  totalGathering: number;
  totalWool: number;
  members: number;
}

import { AttendanceType, Member, AttendanceRecord } from '../types';

const GROUPS = ['사랑', '소망', '믿음', '화평'];
const WOOLS_PER_GROUP = ['A울', 'B울', 'C울'];
const NAMES = ['김철수', '이영희', '박지성', '최동원', '정우성', '한지민', '강동원', '송혜교', '유재석', '강호동'];

// Helper to generate Sundays
export const getSundays = (year: number) => {
  const date = new Date(year, 0, 1);
  const sundays: string[] = [];
  while (date.getDay() !== 0) {
    date.setDate(date.getDate() + 1);
  }
  while (date.getFullYear() === year) {
    sundays.push(date.toISOString().split('T')[0]);
    date.setDate(date.getDate() + 7);
  }
  return sundays;
};

// Generate Members
export const generateMembers = (): Member[] => {
  const members: Member[] = [];
  let idCounter = 1;

  GROUPS.forEach(group => {
    WOOLS_PER_GROUP.forEach(wool => {
      // 3-5 members per wool
      const memberCount = Math.floor(Math.random() * 3) + 3;
      for (let i = 0; i < memberCount; i++) {
        const name = NAMES[Math.floor(Math.random() * NAMES.length)] + idCounter;
        members.push({
          id: `m-${idCounter}`,
          name: name,
          group: group,
          wool: wool,
          prayerRequest: Math.random() > 0.3 ? `${name}의 건강과 학업을 위해 기도해주세요.` : '',
          specialNotes: Math.random() > 0.7 ? '최근 이사함' : '',
        });
        idCounter++;
      }
    });
  });
  return members;
};

// Generate Attendance
export const generateAttendance = (members: Member[], year: number): AttendanceRecord[] => {
  const records: AttendanceRecord[] = [];
  const sundays = getSundays(year);
  let idCounter = 1;

  sundays.forEach(date => {
    members.forEach(member => {
      // Random attendance
      const types: AttendanceType[] = [];
      if (Math.random() > 0.2) types.push(AttendanceType.Worship);
      if (Math.random() > 0.4) types.push(AttendanceType.Gathering);
      if (Math.random() > 0.3) types.push(AttendanceType.Wool);

      if (types.length > 0) {
        records.push({
          id: `a-${idCounter}`,
          memberId: member.id,
          date: date,
          types: types
        });
        idCounter++;
      }
    });
  });

  return records;
};

export const INITIAL_MEMBERS = generateMembers();
export const INITIAL_ATTENDANCE = generateAttendance(INITIAL_MEMBERS, 2024);
export const SUNDAYS_2024 = getSundays(2024);

import { AttendanceRecord, Member, WeeklyStats, AttendanceType, GroupStats } from '../types';

export const getWeeklyStats = (records: AttendanceRecord[], dates: string[]): WeeklyStats[] => {
  return dates.map(date => {
    const dailyRecords = records.filter(r => r.date === date);
    return {
      date,
      worshipCount: dailyRecords.filter(r => r.types.includes(AttendanceType.Worship)).length,
      gatheringCount: dailyRecords.filter(r => r.types.includes(AttendanceType.Gathering)).length,
      woolCount: dailyRecords.filter(r => r.types.includes(AttendanceType.Wool)).length,
    };
  });
};

export const getGroupStats = (members: Member[], records: AttendanceRecord[]): GroupStats[] => {
  const groups = Array.from(new Set(members.map(m => m.group)));

  return groups.map(group => {
    const groupMemberIds = members.filter(m => m.group === group).map(m => m.id);
    const groupRecords = records.filter(r => groupMemberIds.includes(r.memberId));

    return {
      groupName: group,
      members: groupMemberIds.length,
      totalWorship: groupRecords.filter(r => r.types.includes(AttendanceType.Worship)).length,
      totalGathering: groupRecords.filter(r => r.types.includes(AttendanceType.Gathering)).length,
      totalWool: groupRecords.filter(r => r.types.includes(AttendanceType.Wool)).length,
    };
  });
};

export const getAttendanceStatusByMember = (member: Member, records: AttendanceRecord[]): Record<string, AttendanceType[]> => {
  const memberRecords = records.filter(r => r.memberId === member.id);
  const status: Record<string, AttendanceType[]> = {};
  memberRecords.forEach(r => {
    status[r.date] = r.types;
  });
  return status;
};

