import React, { useState, useMemo } from 'react';
import { Member, AttendanceRecord, AttendanceType } from '../types';
import { SUNDAYS_2024 } from '../services/mockData';
import { Check, Minus } from 'lucide-react';

interface AttendanceMatrixProps {
  members: Member[];
  records: AttendanceRecord[];
}

const AttendanceMatrix: React.FC<AttendanceMatrixProps> = ({ members, records }) => {
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth()); // 0-11
  const [filterGroup, setFilterGroup] = useState<string>('all');

  const groups = useMemo(() => Array.from(new Set(members.map(m => m.group))), [members]);
  const months = Array.from({ length: 12 }, (_, i) => i + 1);

  // Filter Sundays for the selected month
  const currentMonthSundays = useMemo(() => {
    return SUNDAYS_2024.filter(date => new Date(date).getMonth() === selectedMonth);
  }, [selectedMonth]);

  // Filter Members
  const filteredMembers = useMemo(() => {
    return filterGroup === 'all' ? members : members.filter(m => m.group === filterGroup);
  }, [members, filterGroup]);

  // Sorting: Group -> Wool -> Name
  const sortedMembers = useMemo(() => {
    return [...filteredMembers].sort((a, b) => {
      if (a.group !== b.group) return a.group.localeCompare(b.group);
      if (a.wool !== b.wool) return a.wool.localeCompare(b.wool);
      return a.name.localeCompare(b.name);
    });
  }, [filteredMembers]);

  const getStatus = (memberId: string, date: string, type: AttendanceType) => {
    const record = records.find(r => r.memberId === memberId && r.date === date && r.types.includes(type));
    return !!record;
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">출석 상세 현황</h2>
          <p className="text-slate-500">소그룹 및 울별 상세 출석부입니다.</p>
        </div>

        <div className="flex gap-4">
            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-32 p-2.5"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(Number(e.target.value))}
            >
              {months.map((m, idx) => (
                <option key={m} value={idx}>{m}월</option>
              ))}
            </select>

            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-40 p-2.5"
              value={filterGroup}
              onChange={(e) => setFilterGroup(e.target.value)}
            >
              <option value="all">전체 소그룹</option>
              {groups.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
            </select>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left text-slate-500">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
              <tr>
                <th scope="col" className="px-4 py-3 sticky left-0 bg-slate-50 z-10 w-24 border-r border-slate-200">이름</th>
                <th scope="col" className="px-4 py-3 w-20 border-r border-slate-200">소그룹/울</th>
                {currentMonthSundays.map(date => (
                  <th key={date} scope="col" className="px-2 py-3 text-center border-r border-slate-200 min-w-[120px]">
                    {date.substring(5)} (일)
                    <div className="flex justify-between text-[10px] mt-1 text-slate-400 px-1">
                      <span>예배</span><span>집회</span><span>울</span>
                    </div>
                  </th>
                ))}
                <th scope="col" className="px-4 py-3 text-center min-w-[80px]">월 합계</th>
              </tr>
            </thead>
            <tbody>
              {sortedMembers.map((member) => (
                <tr key={member.id} className="bg-white border-b hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 font-medium text-slate-900 sticky left-0 bg-white border-r border-slate-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                    {member.name}
                  </td>
                  <td className="px-4 py-3 border-r border-slate-200">
                    <div className="font-semibold text-slate-700">{member.group}</div>
                    <div className="text-xs">{member.wool}</div>
                  </td>
                  {currentMonthSundays.map(date => {
                    const isWorship = getStatus(member.id, date, AttendanceType.Worship);
                    const isGathering = getStatus(member.id, date, AttendanceType.Gathering);
                    const isWool = getStatus(member.id, date, AttendanceType.Wool);
                    return (
                      <td key={date} className="px-2 py-3 border-r border-slate-100">
                        <div className="flex justify-between items-center px-2">
                           <div className={`w-6 h-6 rounded flex items-center justify-center ${isWorship ? 'bg-blue-100 text-blue-600' : 'text-slate-200'}`}>
                             {isWorship ? <Check size={14} strokeWidth={3} /> : <Minus size={14} />}
                           </div>
                           <div className={`w-6 h-6 rounded flex items-center justify-center ${isGathering ? 'bg-indigo-100 text-indigo-600' : 'text-slate-200'}`}>
                             {isGathering ? <Check size={14} strokeWidth={3} /> : <Minus size={14} />}
                           </div>
                           <div className={`w-6 h-6 rounded flex items-center justify-center ${isWool ? 'bg-emerald-100 text-emerald-600' : 'text-slate-200'}`}>
                             {isWool ? <Check size={14} strokeWidth={3} /> : <Minus size={14} />}
                           </div>
                        </div>
                      </td>
                    );
                  })}
                  <td className="px-4 py-3 text-center font-bold text-slate-700">
                    {/* Calculate monthly total for this member (all types combined) */}
                    {currentMonthSundays.reduce((acc, date) => {
                      const dailyCount = records.filter(r => r.memberId === member.id && r.date === date).reduce((c, r) => c + r.types.length, 0);
                      return acc + dailyCount;
                    }, 0)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
         <div className="flex items-center gap-2">
            <div className="w-4 h-4 bg-blue-100 text-blue-600 rounded flex items-center justify-center"><Check size={10} /></div>
            <span>예배 출석</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-4 h-4 bg-indigo-100 text-indigo-600 rounded flex items-center justify-center"><Check size={10} /></div>
            <span>집회 출석</span>
         </div>
         <div className="flex items-center gap-2">
            <div className="w-4 h-4 bg-emerald-100 text-emerald-600 rounded flex items-center justify-center"><Check size={10} /></div>
            <span>울모임 출석</span>
         </div>
      </div>
    </div>
  );
};

export default AttendanceMatrix;

import React, { useMemo } from 'react';
import { Member } from '../types';
import { Quote, AlertCircle } from 'lucide-react';

interface PrayerRequestsProps {
  members: Member[];
}

const PrayerRequests: React.FC<PrayerRequestsProps> = ({ members }) => {
  // Group members by Small Group -> Wool
  const groupedMembers = useMemo(() => {
    const groups: Record<string, Record<string, Member[]>> = {};

    members.forEach(member => {
      if (!groups[member.group]) groups[member.group] = {};
      if (!groups[member.group][member.wool]) groups[member.group][member.wool] = [];
      groups[member.group][member.wool].push(member);
    });

    return groups;
  }, [members]);

  return (
    <div className="space-y-8">
       <header>
        <h2 className="text-3xl font-bold text-slate-800">기도 제목 및 특이사항</h2>
        <p className="text-slate-500">각 울별 멤버들의 기도제목과 특이사항을 확인하세요.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {Object.entries(groupedMembers).map(([groupName, wools]) => (
          <div key={groupName} className="space-y-6">
             <div className="flex items-center gap-2 mb-4 border-b border-slate-200 pb-2">
                <div className="bg-indigo-600 text-white px-3 py-1 rounded-full text-sm font-bold shadow-sm">{groupName} 소그룹</div>
             </div>

             {Object.entries(wools).map(([woolName, members]) => (
               <div key={woolName} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                  <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full mr-2"></span>
                    {woolName}
                  </h3>

                  <div className="space-y-4">
                    {members.map(member => (
                      <div key={member.id} className="relative pl-4 border-l-2 border-slate-100 hover:border-indigo-300 transition-colors">
                        <div className="flex items-baseline justify-between">
                          <h4 className="font-semibold text-slate-800">{member.name}</h4>
                          {member.specialNotes && (
                            <span className="flex items-center text-xs text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full">
                              <AlertCircle size={10} className="mr-1" />
                              {member.specialNotes}
                            </span>
                          )}
                        </div>

                        <div className="mt-2 text-sm text-slate-600 flex items-start">
                          <Quote size={14} className="text-slate-300 mr-2 mt-1 flex-shrink-0" />
                          <p>{member.prayerRequest || <span className="text-slate-400 italic">등록된 기도제목이 없습니다.</span>}</p>
                        </div>
                      </div>
                    ))}
                  </div>
               </div>
             ))}
          </div>
        ))}
      </div>
    </div>
  );
};

export default PrayerRequests;

