  // New Record States
  const [newMember, setNewMember] = useState<Partial<Member>>({ group: '', wool: '', name: '' });
  const [selectedDate, setSelectedDate] = useState<string>(SUNDAYS_2024[SUNDAYS_2024.length - 1]); // Default to last Sunday

  const handleUpdateMember = (id: string, field: keyof Member, value: string) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, [field]: value } : m));
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.group || !newMember.wool) return;
    const id = `m-${Date.now()}`;
    setMembers(prev => [...prev, { id, name: newMember.name!, group: newMember.group!, wool: newMember.wool!, latestPrayerRequest: '', specialNotes: '' }]);
    setNewMember({ group: '', wool: '', name: '' });
  };

  const handleDeleteMember = (id: string) => {
    if (confirm('정말로 삭제하시겠습니까? 관련된 출석 데이터도 함께 삭제되지 않습니다 (유지됨).')) {
      setMembers(prev => prev.filter(m => m.id !== id));
    }
