  const toggleAttendance = (memberId: string, type: AttendanceType) => {
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === selectedDate);
      if (existing) {
        // Toggle type
        const newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id); // Remove record if no types left
        }
        return prev.map(r => r.id === existing.id ? { ...r, types: newTypes } : r);
      } else {
        // Create new record
        return [...prev, {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: selectedDate,
          types: [type]
        }];
      }
    });
  };

  return (
