            >
              출석 입력
            </button>
          </li>
        </ul>
      </div>

      {activeTab === 'members' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
           <div className="flex gap-4 mb-6 items-end bg-slate-50 p-4 rounded-lg">
