import { AttendanceType, Member, AttendanceRecord, PrayerRecord } from '../types';

// Treating these as the unified "Small Group/Wool" names
const GROUPS = ['사랑A', '사랑B', '소망A', '소망B', '믿음A', '믿음B', '화평A'];
const NAMES = ['김철수', '이영희', '박지성', '최동원', '정우성', '한지민', '강동원', '송혜교', '유재석', '강호동'];

// Helper to generate Sundays
export const getSundays = (year: number) => {
  const date = new Date(year, 0, 1);
  const sundays: string[] = [];
  while (date.getDay() !== 0) {
    date.setDate(date.getDate() + 1);
  }
  while (date.getFullYear() === year) {
    sundays.push(date.toISOString().split('T')[0]);
    date.setDate(date.getDate() + 7);
  }
  return sundays;
};

export const SUNDAYS_2024 = getSundays(2024);

// Generate Members
export const generateMembers = (): Member[] => {
  const members: Member[] = [];
  let idCounter = 1;

  GROUPS.forEach(group => {
    // 3-5 members per group
    const memberCount = Math.floor(Math.random() * 3) + 3;
    for (let i = 0; i < memberCount; i++) {
      const name = NAMES[Math.floor(Math.random() * NAMES.length)] + idCounter;
      members.push({
        id: `m-${idCounter}`,
        name: name,
        group: group,
        wool: group, // Syncing wool with group as they are the same concept now
        phoneNumber: `010-${Math.floor(Math.random()*9000)+1000}-${Math.floor(Math.random()*9000)+1000}`,
        specialNotes: Math.random() > 0.8 ? '최근 이사함' : '',
      });
      idCounter++;
    }
  });
  return members;
};

// Generate Attendance
export const generateAttendance = (members: Member[], year: number): AttendanceRecord[] => {
  const records: AttendanceRecord[] = [];
  const sundays = SUNDAYS_2024;
  let idCounter = 1;

  sundays.forEach(date => {
    members.forEach(member => {
      // Random attendance
      const types: AttendanceType[] = [];
      if (Math.random() > 0.2) types.push(AttendanceType.Worship);
      if (Math.random() > 0.4) types.push(AttendanceType.Gathering);
      if (Math.random() > 0.3) types.push(AttendanceType.Wool);

      if (types.length > 0) {
        records.push({
          id: `a-${idCounter}`,
          memberId: member.id,
          date: date,
          types: types
        });
        idCounter++;
      }
    });
  });

  return records;
};

// Generate Prayer Records
export const generatePrayerRecords = (members: Member[]): PrayerRecord[] => {
  const records: PrayerRecord[] = [];
  let idCounter = 1;

  // Generate distinct requests for random sundays
  SUNDAYS_2024.forEach((date, idx) => {
    // Only generate for past/current dates (simulated by index < 10 for demo)
    if (idx < 10) { 
      members.forEach(member => {
        if (Math.random() > 0.7) { // 30% chance to have a prayer request that week
           const requests = [
             "가족의 건강을 위해 기도해주세요.",
             "이번 주 중요한 시험이 있습니다.",
             "직장 동료와의 관계 회복을 위해.",
             "새로운 사업 구상이 잘 진행되길.",
             "영적인 회복과 평안을 위해.",
             "부모님의 수술이 잘 되길.",
             "자녀의 학업 진로를 위해.",
             "전도 대상자가 마음을 열도록."
           ];
           records.push({
             id: `p-${idCounter++}`,
             memberId: member.id,
             date: date,
             content: requests[Math.floor(Math.random() * requests.length)]
           });
        }
      });
    }
  });
  return records;
};

export const INITIAL_MEMBERS = generateMembers();
export const INITIAL_ATTENDANCE = generateAttendance(INITIAL_MEMBERS, 2024);
export const INITIAL_PRAYER_RECORDS = generatePrayerRecords(INITIAL_MEMBERS);

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceMatrix from './components/AttendanceMatrix';
import PrayerRequests from './components/PrayerRequests';
import DataManagement from './components/DataManagement';
import { INITIAL_MEMBERS, INITIAL_ATTENDANCE, INITIAL_PRAYER_RECORDS } from './services/mockData';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType } from './types';

const App: React.FC = () => {
  // Global State
  const [members, setMembers] = useState<Member[]>([]);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [prayerRecords, setPrayerRecords] = useState<PrayerRecord[]>([]);
  const [loading, setLoading] = useState(true);

  // Load initial data
  useEffect(() => {
    // Simulate API Fetch
    setTimeout(() => {
      setMembers(INITIAL_MEMBERS);
      setRecords(INITIAL_ATTENDANCE);
      setPrayerRecords(INITIAL_PRAYER_RECORDS);
      setLoading(false);
    }, 500);
  }, []);

  // Shared Logic to toggle attendance
  const toggleAttendance = (memberId: string, date: string, type: AttendanceType) => {
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === date);
      if (existing) {
        // Toggle type
        const newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id); // Remove record if no types left
        }
        return prev.map(r => r.id === existing.id ? { ...r, types: newTypes } : r);
      } else {
        // Create new record
        return [...prev, {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: date,
          types: [type]
        }];
      }
    });
    // In a real app, you would send an API request here to update the Google Sheet/DB
    console.log(`Updated DB: Member ${memberId} - ${date} - ${type}`);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout>
        <Routes>
          <Route path="/" element={<Dashboard members={members} records={records} />} />
          <Route 
            path="/attendance" 
            element={
              <AttendanceMatrix 
                members={members} 
                records={records} 
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route path="/prayer" element={<PrayerRequests members={members} prayerRecords={prayerRecords} />} />
          <Route 
            path="/manage" 
            element={
              <DataManagement 
                members={members} 
                setMembers={setMembers} 
                records={records} 
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Member, AttendanceRecord, AttendanceType } from '../types';
import { SUNDAYS_2024 } from '../services/mockData';
import { Check } from 'lucide-react';

interface AttendanceMatrixProps {
  members: Member[];
  records: AttendanceRecord[];
  onToggleAttendance: (memberId: string, date: string, type: AttendanceType) => void;
}

const AttendanceMatrix: React.FC<AttendanceMatrixProps> = ({ members, records, onToggleAttendance }) => {
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth()); // 0-11
  const [filterGroup, setFilterGroup] = useState<string>('all');

  const groups = useMemo(() => Array.from(new Set(members.map(m => m.group))), [members]);
  const months = Array.from({ length: 12 }, (_, i) => i + 1);

  // Filter Sundays for the selected month
  const currentMonthSundays = useMemo(() => {
    return SUNDAYS_2024.filter(date => new Date(date).getMonth() === selectedMonth);
  }, [selectedMonth]);

  // Filter Members
  const filteredMembers = useMemo(() => {
    return filterGroup === 'all' ? members : members.filter(m => m.group === filterGroup);
  }, [members, filterGroup]);

  // Sorting: Group -> Name
  const sortedMembers = useMemo(() => {
    return [...filteredMembers].sort((a, b) => {
      if (a.group !== b.group) return a.group.localeCompare(b.group);
      return a.name.localeCompare(b.name);
    });
  }, [filteredMembers]);

  const getStatus = (memberId: string, date: string, type: AttendanceType) => {
    const record = records.find(r => r.memberId === memberId && r.date === date && r.types.includes(type));
    return !!record;
  };

  const calculateTotal = (memberId: string, type: AttendanceType) => {
    return records.filter(r => r.memberId === memberId && currentMonthSundays.includes(r.date) && r.types.includes(type)).length;
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">출석 상세 현황</h2>
          <p className="text-slate-500">클릭하여 출석 상태를 바로 수정할 수 있습니다.</p>
        </div>

        <div className="flex gap-4">
            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-32 p-2.5"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(Number(e.target.value))}
            >
              {months.map((m, idx) => (
                <option key={m} value={idx}>{m}월</option>
              ))}
            </select>

            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-40 p-2.5"
              value={filterGroup}
              onChange={(e) => setFilterGroup(e.target.value)}
            >
              <option value="all">전체 소그룹/울</option>
              {groups.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
            </select>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left text-slate-500 border-collapse">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50">
              <tr>
                <th scope="col" className="px-4 py-3 sticky left-0 bg-slate-50 z-20 w-24 border border-slate-200">이름</th>
                <th scope="col" className="px-4 py-3 w-32 border border-slate-200">소그룹/울</th>
                <th scope="col" className="px-2 py-3 w-16 border border-slate-200 text-center">구분</th>
                {currentMonthSundays.map(date => (
                  <th key={date} scope="col" className="px-2 py-3 text-center border border-slate-200 min-w-[50px]">
                    {date.substring(5)}
                  </th>
                ))}
                <th scope="col" className="px-2 py-3 text-center border border-slate-200 min-w-[50px]">계</th>
              </tr>
            </thead>
            <tbody>
              {sortedMembers.map((member, mIdx) => (
                <React.Fragment key={member.id}>
                  {/* Row 1: Worship */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td rowSpan={3} className={`px-4 py-3 font-medium text-slate-900 sticky left-0 bg-white z-10 border border-slate-200 ${mIdx % 2 === 0 ? 'bg-white' : 'bg-slate-50/50'}`}>
                      {member.name}
                    </td>
                    <td rowSpan={3} className="px-4 py-3 border border-slate-200">
                      <div className="font-semibold text-slate-700">{member.group}</div>
                    </td>
                    <td className="px-2 py-2 text-center text-xs font-bold text-blue-600 border border-slate-200 bg-blue-50">예배</td>
                    {currentMonthSundays.map(date => (
                      <td 
                        key={`${member.id}-${date}-worship`} 
                        onClick={() => onToggleAttendance(member.id, date, AttendanceType.Worship)}
                        className="px-2 py-2 border border-slate-200 text-center cursor-pointer hover:bg-blue-50 transition-colors"
                      >
                        {getStatus(member.id, date, AttendanceType.Worship) && (
                          <div className="flex justify-center text-blue-600">
                             <Check size={16} strokeWidth={3} />
                          </div>
                        )}
                      </td>
                    ))}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Worship)}
                    </td>
                  </tr>

                  {/* Row 2: Gathering */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-indigo-600 border border-slate-200 bg-indigo-50">집회</td>
                    {currentMonthSundays.map(date => (
                      <td 
                        key={`${member.id}-${date}-gathering`} 
                        onClick={() => onToggleAttendance(member.id, date, AttendanceType.Gathering)}
                        className="px-2 py-2 border border-slate-200 text-center cursor-pointer hover:bg-indigo-50 transition-colors"
                      >
                         {getStatus(member.id, date, AttendanceType.Gathering) && (
                          <div className="flex justify-center text-indigo-600">
                             <Check size={16} strokeWidth={3} />
                          </div>
                        )}
                      </td>
                    ))}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Gathering)}
                    </td>
                  </tr>

                  {/* Row 3: Wool */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-emerald-600 border border-slate-200 bg-emerald-50">울</td>
                    {currentMonthSundays.map(date => (
                      <td 
                        key={`${member.id}-${date}-wool`} 
                        onClick={() => onToggleAttendance(member.id, date, AttendanceType.Wool)}
                        className="px-2 py-2 border border-slate-200 text-center cursor-pointer hover:bg-emerald-50 transition-colors"
                      >
                         {getStatus(member.id, date, AttendanceType.Wool) && (
                          <div className="flex justify-center text-emerald-600">
                             <Check size={16} strokeWidth={3} />
                          </div>
                        )}
                      </td>
                    ))}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Wool)}
                    </td>
                  </tr>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

