import React, { useState, useMemo, useEffect } from 'react';
import { Member, AttendanceRecord, AttendanceType, MeetingStatus } from '../types';
import { Plus, Edit2, Save, Trash2, X, Phone, ArrowUpDown, Settings, Link as LinkIcon, AlertCircle, Copy, Check } from 'lucide-react';
import { SUNDAYS_2026 } from '../services/mockData';
import { getScriptUrl, setScriptUrl, fetchSheetData } from '../services/sheetService';

interface DataManagementProps {
  members: Member[];
  setMembers: React.Dispatch<React.SetStateAction<Member[]>>;
  records: AttendanceRecord[];
  meetingStatus: MeetingStatus[];
  onToggleAttendance: (memberId: string, date: string, type: AttendanceType) => void;
  refreshData: () => void;
}

const GAS_CODE_SNIPPET = `
/* 
 [설치 방법]
 1. 구글 스프레드시트 상단 메뉴: 확장 프로그램 > Apps Script
 2. 아래 내용을 모두 붙여넣기 후 저장 (Ctrl+S)
 3. 우측 상단 [배포] > [새 배포] 
    - 유형 선택: 웹 앱
    - 설명: (임의 작성)
    - 다음 사용자 등으로서 실행: '나(웹 앱 소유자)'
    - 액세스 권한 승인: '모든 사용자' (*중요*)
 4. 생성된 '웹 앱 URL'을 복사하여 앱 설정 화면에 입력
*/

function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. Members 시트 가져오기
  // 예상 컬럼: id, name, group, phone
  const rawMembers = getSheetData(ss, 'members');
  const members = rawMembers.map(m => ({
    id: String(m['id'] || m['name']), // ID가 없으면 이름 사용
    name: m['name'],
    group: m['group'],
    wool: m['group'], // group과 wool을 동일하게 처리
    phoneNumber: m['phone'] || m['phonenumber'] || '',
    specialNotes: ''
  })).filter(m => m.name); // 이름 없는 행 제외

  // 2. SessionConfig (모임 설정) 가져오기
  // 예상 컬럼: date, worship, gathering, wool
  // 값: TRUE/체크면 모임 있음, 빈칸이면 모임 없음(Canceled)
  const rawConfig = getSheetData(ss, 'SessionConfig');
  const meetingStatus = [];

  rawConfig.forEach(row => {
    const date = formatDate(row['date']);
    if (!date) return;

    // 시트에 값이 '없으면' 취소된 것으로 처리 (앱 로직: isCanceled=true)
    if (!isChecked(row['worship'])) meetingStatus.push({ date: date, type: '예배', isCanceled: true });
    if (!isChecked(row['gathering'])) meetingStatus.push({ date: date, type: '집회', isCanceled: true });
    if (!isChecked(row['wool'])) meetingStatus.push({ date: date, type: '울모임', isCanceled: true });
  });

  // 3. Attendance (출석 및 기도제목) 가져오기
  // 예상 컬럼: date, memberId, worship, gathering, wool, prayerRequest, note
  const rawAttendance = getSheetData(ss, 'attendance');
  const attendance = [];
  const prayers = [];

  rawAttendance.forEach(row => {
    const date = formatDate(row['date']);
    const memberId = String(row['memberid'] || row['name']); // memberId가 없으면 name 사용
    if (!date || !memberId) return;

    // 출석 처리
    const types = [];
    if (isChecked(row['worship'])) types.push('예배');
    if (isChecked(row['gathering'])) types.push('집회');
    if (isChecked(row['wool'])) types.push('울모임');

    if (types.length > 0) {
      attendance.push({
        id: 'a_' + date + '_' + memberId,
        memberId: memberId,
        date: date,
        types: types
      });
    }

    // 기도제목 처리
    if (row['prayerrequest']) {
      prayers.push({
        id: 'p_' + date + '_' + memberId,
        memberId: memberId,
        date: date,
        content: row['prayerrequest']
      });
    }
  });

  const response = {
    members: members,
    attendance: attendance,
    prayers: prayers,
    meetingStatus: meetingStatus,
    status: 'success'
  };

  return ContentService.createTextOutput(JSON.stringify(response))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let request;
  try {
    request = JSON.parse(e.postData.contents);
  } catch(e) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: 'Invalid JSON'}));
  }

  const { action, payload } = request;
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    if (action === 'UPDATE_ATTENDANCE') {
      // payload: { memberId, date, type, isAdd }
      updateAttendance(ss, payload);
    } else if (action === 'ADD_MEMBER') {
      appendRow(ss, 'members', payload);
    }
  } catch(err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()}));
  } finally {
    lock.releaseLock();
  }

  return ContentService.createTextOutput(JSON.stringify({result: 'success'}))
    .setMimeType(ContentService.MimeType.JSON);
}

// --- Helper Functions ---

function getSheetData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  const range = sheet.getDataRange();
  const values = range.getValues();
  if (values.length < 2) return [];

  const headers = values[0].map(h => String(h).toLowerCase().replace(/\\s/g, ''));
  const data = values.slice(1);

  return data.map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      obj[h] = row[i];
    });
    return obj;
  });
}

function formatDate(dateObj) {
  if (!dateObj) return null;
  if (typeof dateObj === 'string' && dateObj.match(/^\\d{4}-\\d{2}-\\d{2}$/)) return dateObj;
  try {
    // 타임존 한국 시간 기준
    return Utilities.formatDate(new Date(dateObj), 'Asia/Seoul', 'yyyy-MM-dd');
  } catch (e) { return null; }
}

function isChecked(val) {
  if (val === true) return true;
  if (typeof val === 'string') {
    const v = val.trim().toUpperCase();
    return v === 'TRUE' || v === 'O' || v === 'Y' || v === 'YES';
  }
  return false;
}

function updateAttendance(ss, { memberId, date, type, isAdd }) {
  const sheet = ss.getSheetByName('attendance');
  if (!sheet) throw new Error('attendance sheet not found');

  // 간단한 구현: 무조건 행을 추가하는 방식 (로그성)
  // 실제 운영에서는 기존 행을 찾아서 업데이트하는 로직이 더 적합할 수 있으나, 
  // Apps Script의 성능상 로그성으로 쌓고 읽을 때 최신본 혹은 합집합을 쓰는게 빠릅니다.
  // 여기서는 이해를 돕기 위해 'date'와 'memberId'가 일치하는 행을 찾습니다.

  const data = sheet.getDataRange().getValues();
  // 헤더 찾기 (소문자 변환)
  const headers = data[0].map(h => String(h).toLowerCase().replace(/\\s/g, ''));
  const dateIdx = headers.indexOf('date');
  const idIdx = headers.indexOf('memberid');

  // 해당하는 컬럼 인덱스 찾기
  let typeColName = '';
  if (type === '예배') typeColName = 'worship';
  else if (type === '집회') typeColName = 'gathering';
  else if (type === '울모임') typeColName = 'wool';

  const typeIdx = headers.indexOf(typeColName);

  if (dateIdx === -1 || idIdx === -1 || typeIdx === -1) {
    // 컬럼이 없으면 새로 추가하거나 에러 처리
    // 여기서는 단순히 새 행 추가로 처리
    sheet.appendRow([date, memberId, isAdd ? 'TRUE' : 'FALSE', 'Generated by App']);
    return;
  }

  // 기존 행 검색 (역순으로 검색하여 최신 데이터 수정 권장)
  let found = false;
  for (let i = data.length - 1; i >= 1; i--) {
    const rowDate = formatDate(data[i][dateIdx]);
    const rowId = String(data[i][idIdx]);
    if (rowDate === date && rowId === memberId) {
      // 값 업데이트 (row 인덱스는 1부터 시작하므로 i+1)
      sheet.getRange(i + 1, typeIdx + 1).setValue(isAdd);
      found = true;
      break; 
    }
  }

  if (!found && isAdd) {
    // 없는데 추가해야 하는 경우, 새 행 생성
    // 헤더 순서대로 데이터 정렬 필요
    const newRow = new Array(headers.length).fill('');
    newRow[dateIdx] = date;
    newRow[idIdx] = memberId;
    newRow[typeIdx] = true;
    sheet.appendRow(newRow);
  }
}

function appendRow(ss, sheetName, dataObj) {
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(Object.keys(dataObj));
  }
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const row = headers.map(h => dataObj[h.toLowerCase()] || dataObj[h] || '');
  sheet.appendRow(row);
}
`;

