const GAS_CODE_SNIPPET = `
/* 
 [구글 스프레드시트 연결 스크립트 v2.1]

 1. 스프레드시트 메뉴: 확장 프로그램 > Apps Script 클릭
 2. 편집기 화면의 'Code.gs' 파일 내용을 모두 지우고 이 코드를 붙여넣기
