import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from '../types';

const STORAGE_KEY = 'church_admin_script_url';

export const getScriptUrl = () => localStorage.getItem(STORAGE_KEY) || '';
export const setScriptUrl = (url: string) => localStorage.setItem(STORAGE_KEY, url);

interface SheetDataResponse {
  members: Member[];
  attendance: AttendanceRecord[];
  prayers: PrayerRecord[];
  meetingStatus: MeetingStatus[];
  groups: string[]; // Added groups
  status: 'success' | 'error';
  debug_sheets?: string[];
}

export const fetchSheetData = async (): Promise<SheetDataResponse> => {
  const url = getScriptUrl();
  if (!url) throw new Error('URL_NOT_SET');

  try {
    const fetchUrl = `${url}${url.includes('?') ? '&' : '?'}t=${Date.now()}`;
    const response = await fetch(fetchUrl, {
      method: 'GET',
      credentials: 'omit', // Important: Skip cookies to avoid Google Auth issues on 'Anyone' scripts
    });

    if (!response.ok) {
      throw new Error(`서버 응답 오류 (Status: ${response.status})`);
    }

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.indexOf("application/json") === -1) {
      // If response is not JSON (likely HTML), it usually means a Google Login page redirection
      // due to incorrect deployment permissions (not set to "Anyone").
      const text = await response.text();
      console.error("Received non-JSON response:", text.substring(0, 500));
      throw new Error("올바르지 않은 응답 형식입니다. 배포 권한이 '모든 사용자'로 설정되었는지 확인하세요. (HTML 응답 감지됨)");
    }

    const data = await response.json();
    return data;
  } catch (error: any) {
    console.error('Failed to fetch sheet data:', error);
    // Preserve the specific error message if possible
    if (error.message && error.message.includes('Failed to fetch')) {
        throw new Error("서버에 접근할 수 없습니다. URL이 정확한지, 인터넷이 연결되어 있는지 확인하세요. (CORS 오류 가능성)");
    }
    throw error;
  }
};

export const sendAction = async (action: string, payload: any) => {
  const url = getScriptUrl();
  if (!url) return;

  try {
    await fetch(url, {
      method: 'POST',
      mode: 'no-cors', // Opaque response
      credentials: 'omit',
      headers: {
        'Content-Type': 'text/plain',
      },
      body: JSON.stringify({ action, payload }),
    });
  } catch (error) {
    console.error(`Failed to send action ${action}:`, error);
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceMatrix from './components/AttendanceMatrix';
import PrayerRequests from './components/PrayerRequests';
import DataManagement from './components/DataManagement';
import { INITIAL_MEMBERS, INITIAL_ATTENDANCE, INITIAL_PRAYER_RECORDS, INITIAL_MEETING_STATUS } from './services/mockData';
import { fetchSheetData, sendAction, getScriptUrl } from './services/sheetService';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from './types';

const App: React.FC = () => {
  // Global State
  const [members, setMembers] = useState<Member[]>([]);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [prayerRecords, setPrayerRecords] = useState<PrayerRecord[]>([]);
  const [meetingStatus, setMeetingStatus] = useState<MeetingStatus[]>([]);
  const [groups, setGroups] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMock, setUsingMock] = useState(false);

  // Load data function
  const loadData = async () => {
    setLoading(true);
    const scriptUrl = getScriptUrl();

    if (scriptUrl) {
      try {
        const data = await fetchSheetData();
        setMembers(data.members || []);
        setRecords(data.attendance || []);
        setPrayerRecords(data.prayers || []);
        setMeetingStatus(data.meetingStatus || []);

        // If groups are returned from API, use them. Otherwise derive from members.
        if (data.groups && data.groups.length > 0) {
          setGroups(data.groups);
        } else {
          const derivedGroups = Array.from(new Set((data.members || []).map(m => m.group))).sort();
          setGroups(derivedGroups);
        }

        setUsingMock(false);
      } catch (e) {
        console.error("Failed to load live data, falling back to mock", e);
        loadMockData();
        // Keep usingMock false if we want to show error? No, fallback to mock means using mock.
        // But maybe we want to alert the user.
        setUsingMock(true); 
      }
    } else {
      loadMockData();
      setUsingMock(true);
    }
    setLoading(false);
  };

  const loadMockData = () => {
    setMembers(INITIAL_MEMBERS);
    setRecords(INITIAL_ATTENDANCE);
    setPrayerRecords(INITIAL_PRAYER_RECORDS);
    setMeetingStatus(INITIAL_MEETING_STATUS);
    // Derive groups for mock data
    const mockGroups = Array.from(new Set(INITIAL_MEMBERS.map(m => m.group))).sort();
    setGroups(mockGroups);
  };

  useEffect(() => {
    loadData();
  }, []);

  // Shared Logic to toggle attendance
  const toggleAttendance = (memberId: string, date: string, type: AttendanceType) => {
    // Check if meeting is canceled first
    const isCanceled = meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
    if (isCanceled) return;

    // Optimistic UI Update
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === date);
      let updatedRecord: AttendanceRecord | null = null;
      let newTypes: AttendanceType[] = [];

      if (existing) {
        newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        updatedRecord = { ...existing, types: newTypes };

        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: existing.types.includes(type) ? false : true 
        });

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id);
        }
        return prev.map(r => r.id === existing.id ? updatedRecord! : r);
      } else {
        updatedRecord = {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: date,
          types: [type]
        };
        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: true 
        });
        return [...prev, updatedRecord];
      }
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-slate-500">데이터를 불러오는 중입니다...</p>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout>
        {usingMock && (
          <div className="bg-amber-50 border-b border-amber-200 px-4 py-2 text-xs text-amber-700 text-center">
            현재 <strong>데모 데이터</strong>를 보고 있습니다. 실제 스프레드시트와 연결하려면 [데이터 관리 {'>'} DB 연결 설정]을 이용하세요.
          </div>
        )}
        <Routes>
          <Route path="/" element={<Dashboard members={members} records={records} />} />
          <Route 
            path="/attendance" 
            element={
              <AttendanceMatrix 
                members={members} 
                records={records} 
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route path="/prayer" element={<PrayerRequests members={members} prayerRecords={prayerRecords} />} />
          <Route 
            path="/manage" 
            element={
              <DataManagement 
                members={members} 
                setMembers={setMembers} 
                records={records}
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
                refreshData={loadData}
              />
            } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Member, AttendanceRecord, AttendanceType, MeetingStatus } from '../types';
import { SUNDAYS_2026 } from '../services/mockData';
import { Check } from 'lucide-react';

interface AttendanceMatrixProps {
  members: Member[];
  records: AttendanceRecord[];
  meetingStatus: MeetingStatus[];
  availableGroups: string[];
  onToggleAttendance: (memberId: string, date: string, type: AttendanceType) => void;
}

const AttendanceMatrix: React.FC<AttendanceMatrixProps> = ({ members, records, meetingStatus, availableGroups, onToggleAttendance }) => {
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth()); // 0-11
  const [filterGroup, setFilterGroup] = useState<string>('all');

  const months = Array.from({ length: 12 }, (_, i) => i + 1);

  // Filter Sundays for the selected month
  const currentMonthSundays = useMemo(() => {
    return SUNDAYS_2026.filter(date => new Date(date).getMonth() === selectedMonth);
  }, [selectedMonth]);

  // Filter Members
  const filteredMembers = useMemo(() => {
    return filterGroup === 'all' ? members : members.filter(m => m.group === filterGroup);
  }, [members, filterGroup]);

  // Sorting: Group -> Name
  const sortedMembers = useMemo(() => {
    return [...filteredMembers].sort((a, b) => {
      if (a.group !== b.group) return a.group.localeCompare(b.group);
      return a.name.localeCompare(b.name);
    });
  }, [filteredMembers]);

  const getStatus = (memberId: string, date: string, type: AttendanceType) => {
    const record = records.find(r => r.memberId === memberId && r.date === date && r.types.includes(type));
    return !!record;
  };

  const isMeetingCanceled = (date: string, type: AttendanceType) => {
    return meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
  };

  const calculateTotal = (memberId: string, type: AttendanceType) => {
    // Only count if meeting was NOT canceled
    return records.filter(r => {
      const canceled = isMeetingCanceled(r.date, type);
      return !canceled && r.memberId === memberId && currentMonthSundays.includes(r.date) && r.types.includes(type);
    }).length;
  };

  // Render Cell Logic
  const renderCell = (memberId: string, date: string, type: AttendanceType, activeColorClass: string, hoverClass: string) => {
    const canceled = isMeetingCanceled(date, type);

    if (canceled) {
      return (
        <td key={`${memberId}-${date}-${type}`} className="px-2 py-2 border border-slate-200 text-center bg-slate-100 text-slate-400">
           -
        </td>
      );
    }

    const attended = getStatus(memberId, date, type);

    return (
      <td 
        key={`${memberId}-${date}-${type}`} 
        onClick={() => onToggleAttendance(memberId, date, type)}
        className={`px-2 py-2 border border-slate-200 text-center cursor-pointer transition-colors ${hoverClass}`}
      >
        {attended && (
          <div className={`flex justify-center ${activeColorClass}`}>
             <Check size={16} strokeWidth={3} />
          </div>
        )}
      </td>
    );
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">출석 상세 현황</h2>
          <p className="text-slate-500">클릭하여 출석 상태를 바로 수정할 수 있습니다. (회색 칸은 모임 없음)</p>
        </div>

        <div className="flex gap-4">
            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-32 p-2.5"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(Number(e.target.value))}
            >
              {months.map((m, idx) => (
                <option key={m} value={idx}>{m}월</option>
              ))}
            </select>

            <select
              className="bg-white border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block w-40 p-2.5"
              value={filterGroup}
              onChange={(e) => setFilterGroup(e.target.value)}
            >
              <option value="all">전체 소그룹/울</option>
              {availableGroups.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
            </select>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left text-slate-500 border-collapse">
            <thead className="text-xs text-slate-700 uppercase bg-slate-50">
              <tr>
                <th scope="col" className="px-4 py-3 sticky left-0 bg-slate-50 z-20 w-24 border border-slate-200">이름</th>
                <th scope="col" className="px-4 py-3 w-32 border border-slate-200">소그룹/울</th>
                <th scope="col" className="px-2 py-3 w-16 border border-slate-200 text-center">구분</th>
                {currentMonthSundays.map(date => (
                  <th key={date} scope="col" className="px-2 py-3 text-center border border-slate-200 min-w-[50px]">
                    {date.substring(5)}
                  </th>
                ))}
                <th scope="col" className="px-2 py-3 text-center border border-slate-200 min-w-[50px]">계</th>
              </tr>
            </thead>
            <tbody>
              {sortedMembers.map((member, mIdx) => (
                <React.Fragment key={member.id}>
                  {/* Row 1: Worship */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td rowSpan={3} className={`px-4 py-3 font-medium text-slate-900 sticky left-0 bg-white z-10 border border-slate-200 ${mIdx % 2 === 0 ? 'bg-white' : 'bg-slate-50/50'}`}>
                      {member.name}
                    </td>
                    <td rowSpan={3} className="px-4 py-3 border border-slate-200">
                      <div className="font-semibold text-slate-700">{member.group}</div>
                    </td>
                    <td className="px-2 py-2 text-center text-xs font-bold text-blue-600 border border-slate-200 bg-blue-50">예배</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Worship, 'text-blue-600', 'hover:bg-blue-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Worship)}
                    </td>
                  </tr>

                  {/* Row 2: Gathering */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-indigo-600 border border-slate-200 bg-indigo-50">집회</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Gathering, 'text-indigo-600', 'hover:bg-indigo-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Gathering)}
                    </td>
                  </tr>

                  {/* Row 3: Wool */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-emerald-600 border border-slate-200 bg-emerald-50">울</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Wool, 'text-emerald-600', 'hover:bg-emerald-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Wool)}
                    </td>
                  </tr>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

