                            <button onClick={() => onToggleAttendance(member.id, selectedDate, AttendanceType.Gathering)} className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors mx-auto ${types.includes(AttendanceType.Gathering) ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-300'}`}>집</button>
                          }
                        </td>
                        <td className="px-6 py-4 text-center">
                          {isMeetingCanceled(selectedDate, AttendanceType.Wool) ? <span className="text-xs text-slate-400 bg-slate-100 px-2 py-1 rounded">취소됨</span> : 
                            <button onClick={() => onToggleAttendance(member.id, selectedDate, AttendanceType.Wool)} className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors mx-auto ${types.includes(AttendanceType.Wool) ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-300'}`}>울</button>
                          }
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
             </table>
           </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="mb-8">
            <h3 className="text-lg font-bold text-slate-800 mb-2">Google Spreadsheet 데이터베이스 연결</h3>

            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
              <h4 className="font-bold text-blue-800 flex items-center mb-2">
                <HelpCircle size={18} className="mr-2"/>
                "Failed to fetch" 오류가 발생하나요?
              </h4>
              <ul className="list-disc list-inside text-sm text-blue-700 space-y-1">
                <li>배포 시 <strong>'액세스 권한 승인'</strong>을 <strong>'모든 사용자'</strong>로 설정했는지 꼭 확인하세요.</li>
                <li>'본인'이나 'Google 계정 사용자'로 설정하면 연결되지 않습니다.</li>
                <li>스크립트를 수정했다면 <strong>[새 배포]</strong>를 눌러 새 버전을 생성해야 적용됩니다.</li>
                <li>스프레드시트에 <strong>Members</strong>, <strong>SessionConfig</strong>, <strong>Attendance</strong>, <strong>Groups</strong> 시트가 존재해야 합니다.</li>
              </ul>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-6">
              <h4 className="font-bold text-slate-700 mb-2">1단계: 스크립트 복사 및 배포</h4>
              <p className="text-sm text-slate-600 mb-2">
                 아래 코드를 복사하여 Google Spreadsheet &gt; 확장 프로그램 &gt; Apps Script 의 <strong>Code.gs</strong> 파일 내용을 모두 지우고 붙여넣으세요.
              </p>
              <div className="relative group">
                <pre className="bg-slate-800 text-slate-200 p-4 rounded-lg text-xs overflow-x-auto h-48 custom-scrollbar font-mono">
                  {GAS_CODE_SNIPPET}
                </pre>
                <button 
                  onClick={copyToClipboard}
                  className="absolute top-2 right-2 bg-white/10 hover:bg-white/20 text-white p-2 rounded transition-colors"
                  title="코드 복사"
                >
                  {copySuccess ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}
                </button>
              </div>
              <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-md text-sm text-yellow-800">
                <strong>안내:</strong> 말씀하신 데이터베이스 시트 ID(<code>1LoEMB...</code>)가 이미 코드에 적용되어 있습니다. 바로 복사해서 사용하세요.
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
               <h4 className="font-bold text-slate-700 mb-2">2단계: URL 연결</h4>
               <div className="flex gap-2">
                 <input 
                   type="text" 
                   value={scriptUrl}
                   onChange={(e) => setLocalScriptUrl(e.target.value)}
                   placeholder="https://script.google.com/macros/s/......./exec"
                   className="flex-1 border border-slate-300 rounded-lg p-2.5 text-sm"
                 />
                 <button 
                   onClick={handleSaveUrl}
                   disabled={connectionStatus === 'testing'}
                   className={`px-4 py-2 rounded-lg text-white font-medium flex items-center ${
                     connectionStatus === 'testing' ? 'bg-slate-400' : 'bg-indigo-600 hover:bg-indigo-700'
                   }`}
                 >
                   {connectionStatus === 'testing' ? '연결 중...' : <><LinkIcon size={16} className="mr-2"/> 저장 및 테스트</>}
                 </button>
               </div>

               {connectionStatus === 'success' && (
                 <p className="text-xs text-emerald-600 mt-2 font-bold flex items-center">
                   <Check size={14} className="mr-1"/> 연결 성공!
                 </p>
               )}
               {connectionStatus === 'error' && (
                 <div className="mt-2">
                   <p className="text-xs text-rose-500 font-bold flex items-center">
                     <AlertCircle size={14} className="mr-1"/> 연결 실패
                   </p>
                   {errorMessage && <p className="text-xs text-rose-500 mt-1 pl-5">{errorMessage}</p>}
                 </div>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DataManagement;

import React, { useState, useMemo, useEffect } from 'react';
import { Member, PrayerRecord } from '../types';
import { Quote, AlertCircle, Calendar, User, Search } from 'lucide-react';
import { SUNDAYS_2026 } from '../services/mockData';
import { getClosestSunday } from '../services/utils';

interface PrayerRequestsProps {
  members: Member[];
  prayerRecords: PrayerRecord[];
  availableGroups: string[];
}

const PrayerRequests: React.FC<PrayerRequestsProps> = ({ members, prayerRecords, availableGroups }) => {
  const [viewMode, setViewMode] = useState<'member' | 'date'>('date');
  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());

  // Member View State
  const [selectedGroup, setSelectedGroup] = useState<string>('');
  const [selectedMemberId, setSelectedMemberId] = useState<string>('');

  // Initial load effect
  useEffect(() => {
    setSelectedDate(getClosestSunday());
  }, []);

  // When group changes, reset member selection
  useEffect(() => {
    setSelectedMemberId('');
  }, [selectedGroup]);

  // Filter members based on selected group
  const membersInGroup = useMemo(() => {
    if (!selectedGroup) return [];
    return members.filter(m => m.group === selectedGroup).sort((a, b) => a.name.localeCompare(b.name));
  }, [members, selectedGroup]);

  // View 1: By Date - Group by Small Group/Wool directly (Flattened)
  const recordsByDate = useMemo(() => {
    const records = prayerRecords.filter(r => r.date === selectedDate);
    // Group: "Love A" -> [Members...]
    const groups: Record<string, { member: Member; record: PrayerRecord | undefined }[]> = {};

    members.forEach(member => {
       const record = records.find(r => r.memberId === member.id);
       if (!groups[member.group]) groups[member.group] = [];

       // Show if there is a record OR special notes
       if (record || member.specialNotes) {
         groups[member.group].push({ member, record });
       }
    });
    return groups;
  }, [selectedDate, prayerRecords, members]);

  // View 2: By Member - Single Member History
  const selectedMemberData = useMemo(() => {
    if (!selectedMemberId) return null;
    const member = members.find(m => m.id === selectedMemberId);
    if (!member) return null;

    const myRecords = prayerRecords
      .filter(r => r.memberId === member.id)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return { member, records: myRecords };
  }, [selectedMemberId, members, prayerRecords]);

  return (
    <div className="space-y-6">
       <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">기도 제목 및 특이사항</h2>
          <p className="text-slate-500">
            {viewMode === 'date' 
              ? '매주 입력되는 기도제목을 소그룹/울별로 모아서 확인합니다.' 
              : '각 성도님의 기도제목 히스토리를 확인합니다.'}
          </p>
        </div>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button
             onClick={() => setViewMode('date')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'date' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <Calendar size={16} className="mr-2" /> 날짜별 보기
           </button>
           <button
             onClick={() => setViewMode('member')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'member' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <User size={16} className="mr-2" /> 멤버별 보기
           </button>
        </div>
      </header>

      {/* Date View Controls */}
      {viewMode === 'date' && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <label className="font-bold text-slate-700">날짜 선택:</label>
          <select
            className="border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
          >
            {SUNDAYS_2026.slice().reverse().map(d => ( // Show newest first
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      )}

      {/* Member View Controls */}
      {viewMode === 'member' && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
          <div className="flex-1">
             <label className="block text-xs font-bold text-slate-700 mb-1">1. 소그룹/울 선택</label>
             <select
               className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
               value={selectedGroup}
               onChange={(e) => setSelectedGroup(e.target.value)}
             >
               <option value="">소그룹을 선택하세요</option>
               {availableGroups.map(g => (
                 <option key={g} value={g}>{g}</option>
               ))}
             </select>
          </div>
          <div className="flex-1">
             <label className="block text-xs font-bold text-slate-700 mb-1">2. 울원(멤버) 선택</label>
             <select
               className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-400"
               value={selectedMemberId}
               onChange={(e) => setSelectedMemberId(e.target.value)}
               disabled={!selectedGroup}
             >
               <option value="">멤버를 선택하세요</option>
               {membersInGroup.map(m => (
                 <option key={m.id} value={m.id}>{m.name}</option>
               ))}
             </select>
          </div>
        </div>
      )}

      {/* Content Area - Date View */}
      {viewMode === 'date' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Object.entries(recordsByDate).map(([groupName, items]) => {
            if (items.length === 0) return null;
            return (
               <div key={groupName} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                  <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                    <span className="w-2 h-2 bg-indigo-500 rounded-full mr-2"></span>
                    {groupName}
                  </h3>

                  <div className="space-y-4">
                    {items.map(({ member, record }) => (
                      <div key={member.id} className="relative pl-4 border-l-2 border-slate-100 hover:border-indigo-300 transition-colors">
                        <div className="flex items-baseline justify-between">
                          <h4 className="font-semibold text-slate-800">{member.name}</h4>
                          {member.specialNotes && (
                            <span className="flex items-center text-xs text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-100 max-w-[50%] truncate">
                              <AlertCircle size={10} className="mr-1" />
                              {member.specialNotes}
                            </span>
                          )}
                        </div>

                        {record ? (
                          <div className="mt-2 text-sm text-slate-600 flex items-start">
                            <Quote size={14} className="text-slate-300 mr-2 mt-1 flex-shrink-0" />
                            <p>{record.content}</p>
                          </div>
                        ) : (
                          <p className="mt-1 text-xs text-slate-400 italic">이번 주 기도제목 없음</p>
                        )}
                      </div>
                    ))}
                  </div>
              </div>
            );
          })}
          {Object.keys(recordsByDate).length === 0 && (
             <div className="col-span-full text-center py-12 text-slate-400">
               해당 날짜에 등록된 기도제목이 없습니다.
             </div>
          )}
        </div>
      )}

      {/* Content Area - Member View */}
      {viewMode === 'member' && (
         <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[400px]">
            {!selectedMemberData ? (
               <div className="h-full flex flex-col items-center justify-center p-12 text-slate-400">
                  <Search size={48} className="mb-4 opacity-10" />
                  <p>소그룹과 멤버를 선택하여 기록을 확인하세요.</p>
               </div>
            ) : (
               <div className="flex flex-col h-full">
                  <div className="p-6 border-b border-slate-100 bg-slate-50/50 rounded-t-xl">
                     <div className="flex justify-between items-start">
                        <div>
                           <h3 className="font-bold text-2xl text-slate-800">{selectedMemberData.member.name}</h3>
                           <p className="text-sm text-slate-500 mt-1">{selectedMemberData.member.group}</p>
                        </div>
                        {selectedMemberData.member.specialNotes && (
                           <div className="bg-rose-50 border border-rose-100 text-rose-600 px-4 py-2 rounded-lg max-w-md">
                              <p className="text-xs font-bold flex items-center mb-1">
                                 <AlertCircle size={12} className="mr-1" /> 특이사항(비고)
                              </p>
                              <p className="text-sm">{selectedMemberData.member.specialNotes}</p>
                           </div>
                        )}
                     </div>
                  </div>

                  <div className="p-6">
                     <h4 className="text-sm font-bold text-slate-600 mb-4 uppercase tracking-wider">기도제목 히스토리</h4>
                     <div className="space-y-6">
                        {selectedMemberData.records.length > 0 ? (
                           selectedMemberData.records.map(record => (
                              <div key={record.id} className="relative pl-6 border-l-2 border-indigo-100">
                                 <div className="absolute -left-[5px] top-1.5 w-2 h-2 rounded-full bg-indigo-500 ring-4 ring-white"></div>
                                 <span className="text-sm font-bold text-indigo-600 block mb-1">{record.date}</span>
                                 <div className="bg-slate-50 p-4 rounded-lg text-slate-700 text-sm leading-relaxed">
                                    {record.content}
                                 </div>
                              </div>
                           ))
                        ) : (
                           <div className="text-center py-8 text-slate-400 text-sm">
                              <Quote size={24} className="mb-2 opacity-20 mx-auto" />
                              <p>등록된 기도제목 이력이 없습니다.</p>
                           </div>
                        )}
                     </div>
                  </div>
               </div>
            )}
         </div>
      )}
    </div>
  );
};

export default PrayerRequests;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceMatrix from './components/AttendanceMatrix';
import PrayerRequests from './components/PrayerRequests';
import DataManagement from './components/DataManagement';
import { INITIAL_MEMBERS, INITIAL_ATTENDANCE, INITIAL_PRAYER_RECORDS, INITIAL_MEETING_STATUS } from './services/mockData';
import { fetchSheetData, sendAction, getScriptUrl } from './services/sheetService';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from './types';

const App: React.FC = () => {
  // Global State
  const [members, setMembers] = useState<Member[]>([]);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [prayerRecords, setPrayerRecords] = useState<PrayerRecord[]>([]);
  const [meetingStatus, setMeetingStatus] = useState<MeetingStatus[]>([]);
  const [groups, setGroups] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMock, setUsingMock] = useState(false);

  // Load data function
  const loadData = async () => {
    setLoading(true);
    const scriptUrl = getScriptUrl();

    if (scriptUrl) {
      try {
        const data = await fetchSheetData();
        setMembers(data.members || []);
        setRecords(data.attendance || []);
        setPrayerRecords(data.prayers || []);
        setMeetingStatus(data.meetingStatus || []);

        // If groups are returned from API, use them. Otherwise derive from members.
        if (data.groups && data.groups.length > 0) {
          setGroups(data.groups);
        } else {
          const derivedGroups = Array.from(new Set((data.members || []).map(m => m.group))).sort();
          setGroups(derivedGroups);
        }

        setUsingMock(false);
      } catch (e) {
        console.error("Failed to load live data, falling back to mock", e);
        loadMockData();
        // Keep usingMock false if we want to show error? No, fallback to mock means using mock.
        // But maybe we want to alert the user.
        setUsingMock(true); 
      }
    } else {
      loadMockData();
      setUsingMock(true);
    }
    setLoading(false);
  };

  const loadMockData = () => {
    setMembers(INITIAL_MEMBERS);
    setRecords(INITIAL_ATTENDANCE);
    setPrayerRecords(INITIAL_PRAYER_RECORDS);
    setMeetingStatus(INITIAL_MEETING_STATUS);
    // Derive groups for mock data
    const mockGroups = Array.from(new Set(INITIAL_MEMBERS.map(m => m.group))).sort();
    setGroups(mockGroups);
  };

  useEffect(() => {
    loadData();
  }, []);

  // Shared Logic to toggle attendance
  const toggleAttendance = (memberId: string, date: string, type: AttendanceType) => {
    // Check if meeting is canceled first
    const isCanceled = meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
    if (isCanceled) return;

    // Optimistic UI Update
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === date);
      let updatedRecord: AttendanceRecord | null = null;
      let newTypes: AttendanceType[] = [];

      if (existing) {
        newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        updatedRecord = { ...existing, types: newTypes };

        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: existing.types.includes(type) ? false : true 
        });

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id);
        }
        return prev.map(r => r.id === existing.id ? updatedRecord! : r);
      } else {
        updatedRecord = {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: date,
          types: [type]
        };
        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: true 
        });
        return [...prev, updatedRecord];
      }
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-slate-500">데이터를 불러오는 중입니다...</p>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout>
        {usingMock && (
          <div className="bg-amber-50 border-b border-amber-200 px-4 py-2 text-xs text-amber-700 text-center">
            현재 <strong>데모 데이터</strong>를 보고 있습니다. 실제 스프레드시트와 연결하려면 [데이터 관리 {'>'} DB 연결 설정]을 이용하세요.
          </div>
        )}
        <Routes>
          <Route path="/" element={<Dashboard members={members} records={records} />} />
          <Route 
            path="/attendance" 
            element={
              <AttendanceMatrix 
                members={members} 
                records={records} 
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route 
            path="/prayer" 
            element={
              <PrayerRequests 
                members={members} 
                prayerRecords={prayerRecords} 
                availableGroups={groups}
              />
            } 
          />
          <Route 
            path="/manage" 
            element={
              <DataManagement 
                members={members} 
                setMembers={setMembers} 
                records={records}
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
                refreshData={loadData}
              />
            } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

export enum AttendanceType {
  Worship = '예배',
  Gathering = '집회',
  Wool = '울모임'
}

export interface Member {
  id: string;
  name: string;
  group: string; // 소그룹/울 (Combined concept)
  wool: string; // Kept for internal structure if needed, but treated same as group in UI
  phoneNumber?: string; // 연락처
  role?: string; // 직분 (e.g. 성도, 집사, etc.)
  status?: string; // 상태 (e.g. ACTIVE)
  specialNotes?: string;
  latestPrayerRequest?: string; 
}

export interface PrayerRecord {
  id: string;
  memberId: string;
  date: string; // YYYY-MM-DD
  content: string;
}

export interface AttendanceRecord {
  id: string;
  memberId: string;
  date: string; // YYYY-MM-DD
  types: AttendanceType[]; // A member can attend multiple types on one day
}

// New interface to track if a meeting was canceled/not held
export interface MeetingStatus {
  date: string;
  type: AttendanceType;
  isCanceled: boolean;
}

export interface JoinedRecord extends Member {
  attendanceDate?: string;
  attendanceTypes?: AttendanceType[];
}

export interface WeeklyStats {
  date: string;
