  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());
  const [selectedGroupFilter, setSelectedGroupFilter] = useState<string>('all');

  // Update selected date if tab changes to attendance or on mount
  useEffect(() => {
    if (activeTab === 'attendance') {
      setSelectedDate(getClosestSunday());
    }
  }, [activeTab]);

  const handleUpdateMember = (id: string, field: keyof Member, value: string) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, [field]: value } : m));
  };

  const handleAddMember = async () => {
    if (!newMember.name || !newMember.group) {
        alert("이름과 소그룹을 모두 입력해주세요.");
        return;
    }

    // Generate Unique ID: M + 4 random digits
    let id = '';
    let isUnique = false;
    while (!isUnique) {
      const random = Math.floor(1000 + Math.random() * 9000); // 1000-9999
      id = `M${random}`;
      if (!members.some(m => m.id === id)) {
        isUnique = true;
      }
    }

    const memberToAdd: Member = { 
      id, 
      name: newMember.name!, 
      group: newMember.group!, 
      wool: newMember.group!,
      phoneNumber: newMember.phoneNumber || '',
      role: '성도', // Default Role
      status: 'ACTIVE', // Default Status
      latestPrayerRequest: '', 
      specialNotes: '' 
    };

    // 1. Update Local State (Optimistic)
    setMembers(prev => [...prev, memberToAdd]);

    // 2. Send to Google Sheets
    await sendAction('ADD_MEMBER', memberToAdd);

    // 3. Reset Form
    setNewMember({ group: '', name: '', phoneNumber: '' });
    alert(`멤버가 추가되었습니다. (ID: ${id})`);
  };

  const handleSort = (key: keyof Member) => {
    setSortConfig(current => {
      let direction: 'asc' | 'desc' = 'asc';
      // If clicking the same key, toggle direction. If different, start asc.
      if (current && current.key === key) {
        direction = current.direction === 'asc' ? 'desc' : 'asc';
      }
      return { key, direction };
    });
  };

  // Safe Sort Logic - ensure stable sorting without mutation side-effects
  const sortedMembers = useMemo(() => {
    if (!members) return [];

    // Create a fresh copy to sort
    const sortableItems = [...members]; 

    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = (a[sortConfig.key] || '').toString().toLowerCase();
        const bValue = (b[sortConfig.key] || '').toString().toLowerCase();

        if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    } else {
       // Default sort by name if no config
       sortableItems.sort((a, b) => a.name.localeCompare(b.name));
    }
    return sortableItems;
  }, [members, sortConfig]);

  const filteredMembersForAttendance = useMemo(() => {
    if (selectedGroupFilter === 'all') return members;
    return members.filter(m => m.group === selectedGroupFilter);
  }, [members, selectedGroupFilter]);

  const isMeetingCanceled = (date: string, type: AttendanceType) => {
    return meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
