    }
  };

  const handleSort = (key: string) => {
    setSortConfig(current => {
      let direction: 'asc' | 'desc' = 'asc';
      if (current && current.key === key) {
        direction = current.direction === 'asc' ? 'desc' : 'asc';
      }
      return { key, direction };
    });
  };

