                     <th className="px-6 py-3 text-center">예배</th>
                     <th className="px-6 py-3 text-center">집회</th>
                     <th className="px-6 py-3 text-center">울모임</th>
                   </tr>
                </thead>
                <tbody>
                  {processedAttendanceMembers.map(member => {
                    const record = records.find(r => r.memberId === member.id && r.date === selectedDate);
                    const types = record?.types || [];

                    const renderCheckButton = (type: AttendanceType, colorClass: string, activeClass: string) => {
                      if (isMeetingCanceled(selectedDate, type)) {
                        return (
                          <div className="flex justify-center h-full items-center">
                             <div className="w-8 h-8 rounded bg-slate-100 flex items-center justify-center text-slate-300 cursor-not-allowed border border-slate-200">
                                <X size={14} />
                             </div>
                             <span className="sr-only">모임 없음</span>
                          </div>
                        );
                      }
                      const isChecked = types.includes(type);
                      return (
                        <button 
                          onClick={() => onToggleAttendance(member.id, selectedDate, type)} 
                          className={`w-8 h-8 rounded flex items-center justify-center transition-colors mx-auto border ${isChecked ? `${activeClass} border-transparent text-white` : 'bg-white border-slate-300 text-slate-300 hover:border-indigo-300'}`}
                        >
                          {isChecked && <Check size={18} strokeWidth={3} />}
                        </button>
                      );
                    };

                    return (
                      <tr key={member.id} className="bg-white border-b hover:bg-slate-50">
                        <td className="px-6 py-4 font-medium text-slate-900">{member.name}</td>
                        <td className="px-6 py-4">{member.group}</td>
                        <td className="px-6 py-4 text-center">
                          {renderCheckButton(AttendanceType.Worship, '', 'bg-blue-600')}
                        </td>
                        <td className="px-6 py-4 text-center">
                          {renderCheckButton(AttendanceType.Gathering, '', 'bg-indigo-600')}
                        </td>
                        <td className="px-6 py-4 text-center">
                          {renderCheckButton(AttendanceType.Wool, '', 'bg-emerald-600')}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
             </table>
           </div>
        </div>
      )}

      {/* Settings Tab Content (Preserved) */}
      {activeTab === 'settings' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="mb-8">
            <h3 className="text-lg font-bold text-slate-800 mb-2">Google Spreadsheet 데이터베이스 연결</h3>

            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
              <h4 className="font-bold text-blue-800 flex items-center mb-2">
                <HelpCircle size={18} className="mr-2"/>
                "Failed to fetch" 오류가 발생하나요?
              </h4>
              <ul className="list-disc list-inside text-sm text-blue-700 space-y-1">
                <li>배포 시 <strong>'액세스 권한 승인'</strong>을 <strong>'모든 사용자'</strong>로 설정했는지 꼭 확인하세요.</li>
                <li>'본인'이나 'Google 계정 사용자'로 설정하면 연결되지 않습니다.</li>
                <li>스크립트를 수정했다면 <strong>[새 배포]</strong>를 눌러 새 버전을 생성해야 적용됩니다.</li>
                <li>스프레드시트에 <strong>Members</strong>, <strong>SessionConfig</strong>, <strong>Attendance</strong>, <strong>Groups</strong> 시트가 존재해야 합니다.</li>
              </ul>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-6">
              <h4 className="font-bold text-slate-700 mb-2">1단계: 스크립트 복사 및 배포</h4>
              <p className="text-sm text-slate-600 mb-2">
                 아래 코드를 복사하여 Google Spreadsheet &gt; 확장 프로그램 &gt; Apps Script 의 <strong>Code.gs</strong> 파일 내용을 모두 지우고 붙여넣으세요.
              </p>
              <div className="relative group">
                <pre className="bg-slate-800 text-slate-200 p-4 rounded-lg text-xs overflow-x-auto h-48 custom-scrollbar font-mono">
                  {GAS_CODE_SNIPPET}
                </pre>
                <button 
                  onClick={copyToClipboard}
                  className="absolute top-2 right-2 bg-white/10 hover:bg-white/20 text-white p-2 rounded transition-colors"
                  title="코드 복사"
                >
                  {copySuccess ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}
                </button>
              </div>
              <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-md text-sm text-yellow-800">
                <strong>안내:</strong> 말씀하신 데이터베이스 시트 ID(<code>1LoEMB...</code>)가 이미 코드에 적용되어 있습니다. 바로 복사해서 사용하세요.
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
               <h4 className="font-bold text-slate-700 mb-2">2단계: URL 연결</h4>
               <div className="flex gap-2">
                 <input 
                   type="text" 
                   value={scriptUrl}
                   onChange={(e) => setLocalScriptUrl(e.target.value)}
                   placeholder="https://script.google.com/macros/s/......./exec"
                   className="flex-1 border border-slate-300 rounded-lg p-2.5 text-sm"
                 />
                 <button 
                   onClick={handleSaveUrl}
                   disabled={connectionStatus === 'testing'}
                   className={`px-4 py-2 rounded-lg text-white font-medium flex items-center ${
                     connectionStatus === 'testing' ? 'bg-slate-400' : 'bg-indigo-600 hover:bg-indigo-700'
                   }`}
                 >
                   {connectionStatus === 'testing' ? '연결 중...' : <><LinkIcon size={16} className="mr-2"/> 저장 및 테스트</>}
                 </button>
               </div>

               {connectionStatus === 'success' && (
                 <p className="text-xs text-emerald-600 mt-2 font-bold flex items-center">
                   <Check size={14} className="mr-1"/> 연결 성공!
                 </p>
               )}
               {connectionStatus === 'error' && (
                 <div className="mt-2">
                   <p className="text-xs text-rose-500 font-bold flex items-center">
                     <AlertCircle size={14} className="mr-1"/> 연결 실패
                   </p>
                   {errorMessage && <p className="text-xs text-rose-500 mt-1 pl-5">{errorMessage}</p>}
                 </div>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DataManagement;

import React, { useState, useMemo, useEffect } from 'react';
import { Member, PrayerRecord } from '../types';
import { Quote, AlertCircle, Calendar, User, Search, FileText, X } from 'lucide-react';
import { SUNDAYS_2026 } from '../services/mockData';
import { getClosestSunday } from '../services/utils';

interface PrayerRequestsProps {
  members: Member[];
  prayerRecords: PrayerRecord[];
  availableGroups: string[];
}

const PrayerRequests: React.FC<PrayerRequestsProps> = ({ members, prayerRecords, availableGroups }) => {
  const [viewMode, setViewMode] = useState<'member' | 'date'>('date');
  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());

  // Member View State
  const [selectedGroup, setSelectedGroup] = useState<string>('');
  const [selectedMemberId, setSelectedMemberId] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Initial load effect
  useEffect(() => {
    setSelectedDate(getClosestSunday());
  }, []);

  // Filter members based on selected group (for dropdown)
  const membersInGroup = useMemo(() => {
    if (!selectedGroup) return [];
    return members.filter(m => m.group === selectedGroup).sort((a, b) => a.name.localeCompare(b.name));
  }, [members, selectedGroup]);

  // View 1: By Date - Group by Small Group/Wool directly (Flattened)
  const recordsByDate = useMemo(() => {
    const records = prayerRecords.filter(r => r.date === selectedDate);
    const groups: Record<string, { member: Member; record: PrayerRecord | undefined }[]> = {};

    members.forEach(member => {
       const record = records.find(r => r.memberId === member.id);
       if (!groups[member.group]) groups[member.group] = [];

       // Show if there is a record OR special notes OR date-specific notes
       if (record || member.specialNotes) {
         groups[member.group].push({ member, record });
       }
    });
    return groups;
  }, [selectedDate, prayerRecords, members]);

  // View 2: By Member - Search Query OR Single Member OR All in Group
  const memberHistoryData = useMemo(() => {
    let targetMembers: Member[] = [];

    // Priority 1: Search Query
    if (searchQuery.trim()) {
       const query = searchQuery.toLowerCase().trim();
       targetMembers = members.filter(m => m.name.toLowerCase().includes(query));
    }
    // Priority 2: Specific Member Selected via Dropdown
    else if (selectedMemberId) {
      const m = members.find(m => m.id === selectedMemberId);
      if (m) targetMembers = [m];
    } 
    // Priority 3: Group Selected
    else if (selectedGroup) {
      targetMembers = members.filter(m => m.group === selectedGroup).sort((a, b) => a.name.localeCompare(b.name));
    } 
    else {
      return null;
    }

    // Return empty array if search yields no results (distinct from null which means "no selection made")
    if (targetMembers.length === 0) return [];

    // Build data for each target member
    return targetMembers.map(member => {
       const myRecords = prayerRecords
        .filter(r => r.memberId === member.id)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
       return { member, records: myRecords };
    });
  }, [searchQuery, selectedMemberId, selectedGroup, members, prayerRecords]);

  // Handlers to ensure mutual exclusivity between Search vs Dropdowns
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setSearchQuery(val);
    if (val) {
      setSelectedGroup('');
      setSelectedMemberId('');
    }
  };

  const handleGroupChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedGroup(e.target.value);
    setSelectedMemberId(''); // Reset member when group changes
    setSearchQuery(''); // Reset search when using dropdowns
  };

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
    setSearchQuery(''); // Reset search when using dropdowns
  };

  return (
    <div className="space-y-6">
       <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">기도 제목 및 특이사항</h2>
          <p className="text-slate-500">
            {viewMode === 'date' 
              ? '매주 입력되는 기도제목과 특이사항을 소그룹/울별로 확인합니다.' 
              : '각 성도님의 기도제목 및 특이사항 히스토리를 확인합니다.'}
          </p>
        </div>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button
             onClick={() => setViewMode('date')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'date' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <Calendar size={16} className="mr-2" /> 날짜별 보기
           </button>
           <button
             onClick={() => setViewMode('member')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'member' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <User size={16} className="mr-2" /> 멤버별 보기
           </button>
        </div>
      </header>

      {/* Date View Controls */}
      {viewMode === 'date' && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <label className="font-bold text-slate-700">날짜 선택:</label>
          <select
            className="border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
          >
            {SUNDAYS_2026.slice().reverse().map(d => ( // Show newest first
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      )}

      {/* Member View Controls */}
      {viewMode === 'member' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4 md:space-y-0 md:flex md:gap-6 items-end">
          {/* Search Box */}
          <div className="flex-1 w-full">
            <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center text-indigo-700">
              <Search size={14} className="mr-1" /> 이름 직접 검색 (추천)
            </label>
            <div className="relative">
              <input 
                type="text" 
                className="w-full border border-indigo-200 rounded-lg pl-10 pr-4 py-2.5 text-sm focus:ring-indigo-500 focus:border-indigo-500 bg-indigo-50/30"
                placeholder="이름을 입력하세요 (예: 김철수)"
                value={searchQuery}
                onChange={handleSearchChange}
              />
              <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-indigo-400">
                <Search size={18} />
              </div>
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-400 hover:text-slate-600"
                >
                  <X size={16} />
                </button>
              )}
            </div>
          </div>

          <div className="hidden md:flex items-center justify-center pb-3 px-2 text-slate-300 font-bold text-sm">OR</div>
          <div className="md:hidden text-center text-xs text-slate-400 my-2">- 또는 소그룹으로 찾기 -</div>

          {/* Dropdowns */}
          <div className="flex-1 w-full flex gap-3">
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">소그룹 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
                 value={selectedGroup}
                 onChange={handleGroupChange}
               >
                 <option value="">선택 안 함</option>
                 {availableGroups.map(g => (
                   <option key={g} value={g}>{g}</option>
                 ))}
               </select>
            </div>
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">멤버 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-400"
                 value={selectedMemberId}
                 onChange={handleMemberChange}
                 disabled={!selectedGroup}
               >
                 <option value="">전체 보기</option>
                 {membersInGroup.map(m => (
                   <option key={m.id} value={m.id}>{m.name}</option>
                 ))}
               </select>
            </div>
          </div>
        </div>
      )}

      {/* Content Area - Date View */}
      {viewMode === 'date' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Object.entries(recordsByDate).map(([groupName, items]) => {
            const groupItems = items as { member: Member; record: PrayerRecord | undefined }[];
            if (groupItems.length === 0) return null;
            return (
               <div key={groupName} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                  <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                    <span className="w-2 h-2 bg-indigo-500 rounded-full mr-2"></span>
                    {groupName}
                  </h3>

                  <div className="space-y-4">
                    {groupItems.map(({ member, record }) => (
                      <div key={member.id} className="relative pl-4 border-l-2 border-slate-100 hover:border-indigo-300 transition-colors">
                        <div className="flex items-baseline justify-between">
                          <h4 className="font-semibold text-slate-800">{member.name}</h4>
                          {member.specialNotes && (
                            <span className="flex items-center text-xs text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-100 max-w-[50%] truncate">
                              <AlertCircle size={10} className="mr-1" />
                              {member.specialNotes}
                            </span>
                          )}
                        </div>

                        {record && (
                           <>
                             {record.content && (
                               <div className="mt-2 text-sm text-slate-600 flex items-start">
                                 <Quote size={14} className="text-slate-300 mr-2 mt-1 flex-shrink-0" />
                                 <p>{record.content}</p>
                               </div>
                             )}
                             {record.note && (
                               <div className="mt-2 text-sm text-slate-700 flex items-start bg-yellow-50 p-2 rounded border border-yellow-100">
                                 <FileText size={14} className="text-yellow-600 mr-2 mt-0.5 flex-shrink-0" />
                                 <p>{record.note}</p>
                               </div>
                             )}
                           </>
                        )}
                        {(!record || (!record.content && !record.note)) && (
                          <p className="mt-1 text-xs text-slate-400 italic">기록 없음</p>
                        )}
                      </div>
                    ))}
                  </div>
              </div>
            );
          })}
          {Object.keys(recordsByDate).length === 0 && (
             <div className="col-span-full text-center py-12 text-slate-400">
               해당 날짜에 등록된 내용이 없습니다.
             </div>
          )}
        </div>
      )}

      {/* Content Area - Member View */}
      {viewMode === 'member' && (
         <div className="space-y-6">
            {!memberHistoryData ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[400px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <Search size={48} className="mb-4 opacity-10" />
                  <p>위에서 이름을 검색하거나, 소그룹을 선택하여 기록을 확인하세요.</p>
               </div>
            ) : memberHistoryData.length === 0 ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[300px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <AlertCircle size={48} className="mb-4 opacity-10" />
                  <p>검색 결과가 없습니다.</p>
               </div>
            ) : (
               memberHistoryData.map(({ member, records }) => (
                 <div key={member.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="p-6 border-b border-slate-100 bg-slate-50/50">
                       <div className="flex justify-between items-start">
                          <div>
                             <h3 className="font-bold text-2xl text-slate-800">{member.name}</h3>
                             <p className="text-sm text-slate-500 mt-1">{member.group}</p>
                          </div>
                          {member.specialNotes && (
                             <div className="bg-rose-50 border border-rose-100 text-rose-600 px-4 py-2 rounded-lg max-w-md">
                                <p className="text-xs font-bold flex items-center mb-1">
                                   <AlertCircle size={12} className="mr-1" /> 기본 비고
                                </p>
                                <p className="text-sm">{member.specialNotes}</p>
                             </div>
                          )}
                       </div>
                    </div>

                    <div className="p-6">
                       <h4 className="text-sm font-bold text-slate-600 mb-4 uppercase tracking-wider">히스토리</h4>
                       <div className="space-y-6">
                          {records.length > 0 ? (
                             records.map(record => (
                                <div key={record.id} className="relative pl-6 border-l-2 border-indigo-100">
                                   <div className="absolute -left-[5px] top-1.5 w-2 h-2 rounded-full bg-indigo-500 ring-4 ring-white"></div>
                                   <span className="text-sm font-bold text-indigo-600 block mb-1">{record.date}</span>
                                   <div className="space-y-2">
                                       {record.content && (
                                         <div className="bg-slate-50 p-4 rounded-lg text-slate-700 text-sm leading-relaxed border border-slate-100">
                                            <div className="flex items-center text-xs text-slate-400 mb-1">
                                              <Quote size={12} className="mr-1"/> 기도제목
                                            </div>
                                            {record.content}
                                         </div>
                                       )}
                                       {record.note && (
                                         <div className="bg-yellow-50 p-3 rounded-lg text-slate-700 text-sm leading-relaxed border border-yellow-100">
                                            <div className="flex items-center text-xs text-yellow-600 mb-1 font-bold">
                                              <FileText size={12} className="mr-1"/> 특이사항
                                            </div>
                                            {record.note}
                                         </div>
                                       )}
                                   </div>
                                </div>
                             ))
                          ) : (
                             <div className="text-center py-4 text-slate-400 text-sm">
                                <p>등록된 이력이 없습니다.</p>
                             </div>
                          )}
                       </div>
                    </div>
                 </div>
               ))
            )}
         </div>
      )}
    </div>
  );
};

export default PrayerRequests;

