import * as XLSX from 'xlsx';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType } from '../types';

interface ExportOptions {
  startDate: string;
  endDate: string;
}

/**
 * Main function to trigger Excel download
 */
export const exportDataToExcel = (
  members: Member[],
  attendanceRecords: AttendanceRecord[],
  prayerRecords: PrayerRecord[],
  groups: string[],
  options: ExportOptions
) => {
  const wb = XLSX.utils.book_new();
  const { startDate, endDate } = options;

  // 1. Filter Records by Date Range
  const filteredAttendance = attendanceRecords.filter(r => r.date >= startDate && r.date <= endDate);
  const filteredPrayers = prayerRecords.filter(r => r.date >= startDate && r.date <= endDate);

  // Get all unique dates in the range (sorted)
  const dateSet = new Set<string>();
  filteredAttendance.forEach(r => dateSet.add(r.date));
  filteredPrayers.forEach(r => dateSet.add(r.date));
  const sortedDates = Array.from(dateSet).sort();

  // Sort Members by Group -> Name
  const sortedMembers = [...members].sort((a, b) => {
    if (a.group !== b.group) return a.group.localeCompare(b.group);
    return a.name.localeCompare(b.name);
  });

  // --- SHEET 1: 출석 상세 (Attendance Matrix) ---
  const attendanceSheetData = generateAttendanceMatrix(sortedMembers, filteredAttendance, sortedDates);
  const wsAttendance = XLSX.utils.aoa_to_sheet(attendanceSheetData);

  // Set column widths
  const wscolsAtt = [{ wch: 10 }, { wch: 15 }, { wch: 10 }]; // Name, Group, Role
  sortedDates.forEach(() => wscolsAtt.push({ wch: 12 })); // Date columns
  wsAttendance['!cols'] = wscolsAtt;

  XLSX.utils.book_append_sheet(wb, wsAttendance, "출석_상세현황");

  // --- SHEET 2: 기도제목 목록 (Prayer Requests) ---
  const prayerSheetData = generatePrayerList(sortedMembers, filteredPrayers);
  const wsPrayer = XLSX.utils.json_to_sheet(prayerSheetData);

  // Set column widths
  wsPrayer['!cols'] = [
    { wch: 12 }, // Date
    { wch: 15 }, // Group
    { wch: 10 }, // Name
    { wch: 50 }, // Content
    { wch: 30 }  // Note
  ];

  XLSX.utils.book_append_sheet(wb, wsPrayer, "기도제목_목록");

  // --- SHEET 3: 종합 통계 (Summary Stats) ---
  const statsSheetData = generateStatsSummary(sortedMembers, filteredAttendance);
  const wsStats = XLSX.utils.json_to_sheet(statsSheetData);
  wsStats['!cols'] = [{ wch: 15 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }];

  XLSX.utils.book_append_sheet(wb, wsStats, "기간별_종합통계");

  // Generate File
  const fileName = `소그룹_출석관리_${startDate}_${endDate}.xlsx`;
  XLSX.writeFile(wb, fileName);
};

// --- Helper: Generate Attendance Matrix (Array of Arrays) ---
const generateAttendanceMatrix = (members: Member[], records: AttendanceRecord[], dates: string[]) => {
  // Header Row
  const header = ["이름", "소그룹", "직분", ...dates];

  // Data Rows
  const rows = members.map(member => {
    const row = [member.name, member.group, member.role || '성도'];

    dates.forEach(date => {
      const record = records.find(r => r.memberId === member.id && r.date === date);
      if (record && record.types.length > 0) {
        // Format: W, G, L
        const codes = record.types.map(t => {
          if (t === AttendanceType.Worship) return 'W(예배)';
          if (t === AttendanceType.Gathering) return 'G(집회)';
          if (t === AttendanceType.Wool) return 'L(울)';
          return '';
        }).join(', ');
        row.push(codes);
      } else {
        row.push('');
      }
    });
    return row;
  });

  return [header, ...rows];
};

// --- Helper: Generate Prayer List (Array of Objects) ---
const generatePrayerList = (members: Member[], prayers: PrayerRecord[]) => {
  // Sort prayers by Group -> Date -> Name
  const enrichedPrayers = prayers.map(p => {
    const member = members.find(m => m.id === p.memberId);
    return {
      date: p.date,
      group: member?.group || '미지정',
      name: member?.name || '알수없음',
      content: p.content,
      note: p.note
    };
  });

  enrichedPrayers.sort((a, b) => {
    if (a.group !== b.group) return a.group.localeCompare(b.group);
    if (a.date !== b.date) return b.date.localeCompare(a.date); // Newest first
    return a.name.localeCompare(b.name);
  });

  return enrichedPrayers.map(p => ({
    "날짜": p.date,
    "소그룹": p.group,
    "이름": p.name,
    "기도제목": p.content || '',
    "특이사항": p.note || ''
  }));
};

// --- Helper: Generate Stats Summary ---
const generateStatsSummary = (members: Member[], records: AttendanceRecord[]) => {
  return members.map(member => {
    const myRecords = records.filter(r => r.memberId === member.id);
    const wCount = myRecords.filter(r => r.types.includes(AttendanceType.Worship)).length;
    const gCount = myRecords.filter(r => r.types.includes(AttendanceType.Gathering)).length;
    const lCount = myRecords.filter(r => r.types.includes(AttendanceType.Wool)).length;

    return {
      "소그룹": member.group,
      "이름": member.name,
      "예배 참석": wCount,
      "집회 참석": gCount,
      "울모임 참석": lCount,
      "총 출석일수": myRecords.length // Unique days attended at least one meeting
    };
  });
};

