import * as XLSX from 'xlsx';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from '../types';

interface ExportOptions {
  startDate: string;
  endDate: string;
}

/**
 * Main function to trigger Excel download
 */
export const exportDataToExcel = (
  members: Member[],
  attendanceRecords: AttendanceRecord[],
  prayerRecords: PrayerRecord[],
  meetingStatus: MeetingStatus[],
  groups: string[],
  options: ExportOptions
) => {
  const wb = XLSX.utils.book_new();
  const { startDate, endDate } = options;

  // 1. Filter Records by Date Range
  const filteredAttendance = attendanceRecords.filter(r => r.date >= startDate && r.date <= endDate);
  const filteredPrayers = prayerRecords.filter(r => r.date >= startDate && r.date <= endDate);

  // Filter Meeting Status
  const filteredMeetingStatus = meetingStatus.filter(s => s.date >= startDate && s.date <= endDate);

  // Get all unique dates in the range (sorted)
  const dateSet = new Set<string>();
  filteredAttendance.forEach(r => dateSet.add(r.date));
  filteredPrayers.forEach(r => dateSet.add(r.date));
  // Ensure we include dates that might have canceled meetings even if no attendance
  filteredMeetingStatus.forEach(s => dateSet.add(s.date));

  const sortedDates = Array.from(dateSet).sort();

  // --- SHEET 1: 종합 통계 (Summary Stats) ---
  const statsSheetData = generateStatsSummary(members, filteredAttendance);
  const wsStats = XLSX.utils.json_to_sheet(statsSheetData);
  wsStats['!cols'] = [{ wch: 15 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }];
  XLSX.utils.book_append_sheet(wb, wsStats, "종합통계");

  // --- SHEET 2: 전체 출석부 (Master Matrix) ---
  const allMembersSorted = [...members].sort((a, b) => {
    if (a.group !== b.group) return a.group.localeCompare(b.group);
    return a.name.localeCompare(b.name);
  });
  const attendanceSheetData = generateAttendanceMatrix(allMembersSorted, filteredAttendance, filteredMeetingStatus, sortedDates);
  const wsAttendance = XLSX.utils.aoa_to_sheet(attendanceSheetData);
  setAttendanceColumnWidths(wsAttendance, sortedDates.length);
  XLSX.utils.book_append_sheet(wb, wsAttendance, "전체출석부");

  // --- SHEET 3 ~ N: Group Specific Sheets (Attendance + Prayers) ---
  groups.forEach(group => {
    const groupMembers = members.filter(m => m.group === group).sort((a, b) => a.name.localeCompare(b.name));
    if (groupMembers.length === 0) return;

    // A. Create Attendance Section
    const groupMatrix = generateAttendanceMatrix(groupMembers, filteredAttendance, filteredMeetingStatus, sortedDates);

    // B. Create Prayer Section
    const groupPrayers = filteredPrayers.filter(p => groupMembers.some(m => m.id === p.memberId));
    const prayerRows = generateSimplePrayerRows(groupMembers, groupPrayers);

    // Combine: Matrix + Empty Row + Title + Prayer Rows
    const combinedData = [
      ...groupMatrix,
      [], // Empty row
      ["[기도제목 및 특이사항]"], // Section Title
      ["날짜", "이름", "내용", "비고"], // Header
      ...prayerRows
    ];

    const wsGroup = XLSX.utils.aoa_to_sheet(combinedData);
    setAttendanceColumnWidths(wsGroup, sortedDates.length);

    // Add sheet
    // Excel sheet names max 31 chars
    const sheetName = group.length > 25 ? group.substring(0, 25) : group;
    XLSX.utils.book_append_sheet(wb, wsGroup, sheetName);
  });

  // Generate File
  const fileName = `소그룹_출석관리_${startDate}_${endDate}.xlsx`;
  XLSX.writeFile(wb, fileName);
};

// --- Helper: Generate Attendance Matrix (Array of Arrays) ---
const generateAttendanceMatrix = (
  members: Member[], 
  records: AttendanceRecord[], 
  meetingStatus: MeetingStatus[],
  dates: string[]
) => {
  // 1. Header Row
  // Format dates as MM/DD for compactness
  const dateHeaders = dates.map(d => d.substring(5).replace('-', '/'));
  const header = ["소그룹", "이름", "직분", ...dateHeaders];

  // 2. Data Rows
  const rows = members.map(member => {
    const row = [member.group, member.name, member.role || '성도'];

    dates.forEach(date => {
      // Check cancellation
      const wCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Worship && s.isCanceled);
      const gCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Gathering && s.isCanceled);
      const lCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Wool && s.isCanceled);

      const record = records.find(r => r.memberId === member.id && r.date === date);
      const types = record ? record.types : [];

      const parts = [];

      // Logic: If attended, show symbol. If not attended AND canceled, show '-'. If not attended and not canceled, show empty.

      // Worship
      if (types.includes(AttendanceType.Worship)) parts.push("예");
      else if (wCanceled) { /* parts.push("-"); */ } // Only show dash if ALL are canceled? Or specific position? 
      // Let's simplify: If they attended anything, show it.

      // Gathering
      if (types.includes(AttendanceType.Gathering)) parts.push("집");

      // Wool
      if (types.includes(AttendanceType.Wool)) parts.push("울");

      if (parts.length > 0) {
        row.push(parts.join('/'));
      } else {
        // If nothing attended, check if ALL meetings were canceled that day?
        // Or just show '-' if primary meetings (Worship/Wool) were canceled?
        if (wCanceled && lCanceled) {
          row.push("-");
        } else {
          row.push("");
        }
      }
    });
    return row;
  });

  return [header, ...rows];
};

// --- Helper: Generate Prayer Rows for Group Sheet ---
const generateSimplePrayerRows = (members: Member[], prayers: PrayerRecord[]) => {
  // Sort by Date Descending
  const sortedPrayers = [...prayers].sort((a, b) => b.date.localeCompare(a.date));

  if (sortedPrayers.length === 0) return [["기록된 기도제목이 없습니다."]];

  return sortedPrayers.map(p => {
    const member = members.find(m => m.id === p.memberId);
    return [
      p.date,
      member?.name || '알수없음',
      p.content || '',
      p.note || ''
    ];
  });
};

// --- Helper: Generate Stats Summary ---
const generateStatsSummary = (members: Member[], records: AttendanceRecord[]) => {
  return members.map(member => {
    const myRecords = records.filter(r => r.memberId === member.id);
    const wCount = myRecords.filter(r => r.types.includes(AttendanceType.Worship)).length;
    const gCount = myRecords.filter(r => r.types.includes(AttendanceType.Gathering)).length;
    const lCount = myRecords.filter(r => r.types.includes(AttendanceType.Wool)).length;

    return {
      "소그룹": member.group,
      "이름": member.name,
      "예배 참석": wCount,
      "집회 참석": gCount,
      "울모임 참석": lCount,
      "총 출석일수": myRecords.length 
    };
  });
};

const setAttendanceColumnWidths = (ws: XLSX.WorkSheet, dateCount: number) => {
  const cols = [
    { wch: 15 }, // Group
    { wch: 10 }, // Name
    { wch: 8 },  // Role
  ];
  // Date columns width
  for(let i=0; i<dateCount; i++) {
    cols.push({ wch: 8 });
  }
  ws['!cols'] = cols;
};

