    // 집회
    const gVal = row['gathering'] || row['meeting'] || row['집회'] || row['hasassembly'] || row['assembly'];
    if (!isChecked(gVal)) meetingStatus.push({ date: date, type: '집회', isCanceled: true });

    // 울모임
