import * as XLSX from 'xlsx';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from '../types';

interface ExportOptions {
  startDate: string;
  endDate: string;
}

/**
 * Main function to trigger Excel download
 */
export const exportDataToExcel = (
  members: Member[],
  attendanceRecords: AttendanceRecord[],
  prayerRecords: PrayerRecord[],
  meetingStatus: MeetingStatus[],
  groups: string[],
  options: ExportOptions
) => {
  const wb = XLSX.utils.book_new();
  const { startDate, endDate } = options;

  // 1. Filter Records by Date Range
  const filteredAttendance = attendanceRecords.filter(r => r.date >= startDate && r.date <= endDate);
  const filteredPrayers = prayerRecords.filter(r => r.date >= startDate && r.date <= endDate);

  // 2. Identify all relevant dates (Sorted)
  const dateSet = new Set<string>();
  filteredAttendance.forEach(r => dateSet.add(r.date));
  filteredPrayers.forEach(r => dateSet.add(r.date));
  meetingStatus.filter(s => s.date >= startDate && s.date <= endDate).forEach(s => dateSet.add(s.date));

  const sortedDates = Array.from(dateSet).sort();
  // Header Format: MM/DD
  const dateHeaders = sortedDates.map(d => d.substring(5).replace('-', '/')); 

  // --- Create Sheet per Group ---
  groups.forEach(group => {
    const groupMembers = members.filter(m => m.group === group).sort((a, b) => a.name.localeCompare(b.name));
    if (groupMembers.length === 0) return;

    const sheetData: any[][] = [];
    const merges: XLSX.Range[] = [];

    // Row 1: Group Name
    sheetData.push([group]); 

    // Row 2: Empty Spacer
    sheetData.push([]); 

    // === SECTION 1: ATTENDANCE MATRIX ===

    // Row 3: Headers
    sheetData.push(["이름", "구분", ...dateHeaders]);

    // Data Rows
    let currentRow = 3; // 0-based index, so Row 4 is index 3

    groupMembers.forEach(member => {
      // Each member has 3 rows: Worship, Gathering, Wool
      const rowW = [member.name, "예배"];
      const rowG = [member.name, "집회"]; // Name repeated (will be covered by merge)
      const rowL = [member.name, "울모임"];

      sortedDates.forEach(date => {
        // 1. Worship
        const wCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Worship && s.isCanceled);
        const wAttended = filteredAttendance.some(r => r.memberId === member.id && r.date === date && r.types.includes(AttendanceType.Worship));
        rowW.push(getStatusSymbol(wAttended, wCanceled));

        // 2. Gathering
        const gCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Gathering && s.isCanceled);
        const gAttended = filteredAttendance.some(r => r.memberId === member.id && r.date === date && r.types.includes(AttendanceType.Gathering));
        rowG.push(getStatusSymbol(gAttended, gCanceled));

        // 3. Wool
        const lCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Wool && s.isCanceled);
        const lAttended = filteredAttendance.some(r => r.memberId === member.id && r.date === date && r.types.includes(AttendanceType.Wool));
        rowL.push(getStatusSymbol(lAttended, lCanceled));
      });

      sheetData.push(rowW);
      sheetData.push(rowG);
      sheetData.push(rowL);

      // Merge Name Cell (Column 0, across 3 rows)
      merges.push({ s: { r: currentRow, c: 0 }, e: { r: currentRow + 2, c: 0 } });

      currentRow += 3;
    });

    // === SECTION 2: PRAYER REQUESTS ===

    // Spacer Rows
    sheetData.push([]);

    // Section Title
    sheetData.push(["[기도제목 및 특이사항]"]);

    // Headers
    sheetData.push(["이름", "비고", ...dateHeaders]);

    groupMembers.forEach(member => {
      // Row: Name, Memo (SpecialNotes), Date1 Content, Date2 Content...
      const row = [member.name, member.specialNotes || ''];

      sortedDates.forEach(date => {
        const records = filteredPrayers.filter(p => p.memberId === member.id && p.date === date);
        const content = records.map(p => {
            const c = p.content || '';
            const n = p.note ? `(특이사항: ${p.note})` : '';
            return c + (c && n ? '\n' : '') + n;
        }).filter(Boolean).join('\n');

        row.push(content);
      });

      sheetData.push(row);
    });

    // Create Sheet
    const ws = XLSX.utils.aoa_to_sheet(sheetData);

    // Apply Merges
    if (merges.length > 0) {
      ws['!merges'] = merges;
    }

    // Set Column Widths
    const cols = [
      { wch: 10 }, // Name
      { wch: 10 }, // Type / Memo
    ];
    // Date columns - slightly wider for prayer content
    dateHeaders.forEach(() => cols.push({ wch: 15 })); 
    ws['!cols'] = cols;

    // Append to Workbook (Sheet name limited to 31 chars)
    const safeSheetName = group.replace(/[\\/?*[\]]/g, '').substring(0, 30) || "Group";
    XLSX.utils.book_append_sheet(wb, ws, safeSheetName);
  });

  // Generate File
  const fileName = `소그룹_출석부_${startDate}_${endDate}.xlsx`;
  XLSX.writeFile(wb, fileName);
};

// Helper to determine cell symbol
function getStatusSymbol(attended: boolean, canceled: boolean): string {
  if (attended) return 'O';
  if (canceled) return '-';
  return 'X';
}

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceMatrix from './components/AttendanceMatrix';
import PrayerRequests from './components/PrayerRequests';
import DataManagement from './components/DataManagement';
import IndividualProfile from './components/IndividualProfile';
import { INITIAL_MEMBERS, INITIAL_ATTENDANCE, INITIAL_PRAYER_RECORDS, INITIAL_MEETING_STATUS } from './services/mockData';
import { fetchSheetData, sendAction, getScriptUrl } from './services/sheetService';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from './types';

const App: React.FC = () => {
  // Global State
  const [members, setMembers] = useState<Member[]>([]);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [prayerRecords, setPrayerRecords] = useState<PrayerRecord[]>([]);
  const [meetingStatus, setMeetingStatus] = useState<MeetingStatus[]>([]);
  const [groups, setGroups] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMock, setUsingMock] = useState(false);

  // Filter only Active members for the app views (except DataManagement)
  const activeMembers = useMemo(() => {
    return members.filter(m => m.status !== 'INACTIVE');
  }, [members]);

  // Function to clean attendance records based on meeting status
  // This ensures that if a meeting is canceled (FALSE in DB), any accidental 'Present' record is ignored.
  const cleanAttendanceData = (rawRecords: AttendanceRecord[], rawStatus: MeetingStatus[]): AttendanceRecord[] => {
    return rawRecords.map(record => {
      // Filter out types that are marked as canceled in the meeting status
      const validTypes = record.types.filter(type => {
        const statusForDateAndType = rawStatus.find(s => s.date === record.date && s.type === type);
        // If status exists and isCanceled is true, drop this attendance type
        if (statusForDateAndType && statusForDateAndType.isCanceled) {
          return false;
        }
        return true;
      });

      return { ...record, types: validTypes };
    }).filter(record => record.types.length > 0); // Remove records that became empty
  };

  // Load data function
  const loadData = async () => {
    setLoading(true);
    const scriptUrl = getScriptUrl();

    if (scriptUrl) {
      try {
        const data = await fetchSheetData();

        const fetchedMembers = data.members || [];
        const fetchedMeetingStatus = data.meetingStatus || [];
        const fetchedRecords = data.attendance || [];
        const fetchedPrayers = data.prayers || [];

        // 1. Set Basic Data
        setMembers(fetchedMembers);
        setMeetingStatus(fetchedMeetingStatus);
        setPrayerRecords(fetchedPrayers);

        // 2. Clean Attendance Records (Requirement 1: Strict consistency)
        const cleanedRecords = cleanAttendanceData(fetchedRecords, fetchedMeetingStatus);
        setRecords(cleanedRecords);

        // If groups are returned from API, use them. Otherwise derive from members.
        if (data.groups && data.groups.length > 0) {
          setGroups(data.groups);
        } else {
          const derivedGroups = Array.from(new Set(fetchedMembers.map(m => m.group))).sort();
          setGroups(derivedGroups);
        }

        setUsingMock(false);
      } catch (e) {
        console.error("Failed to load live data, falling back to mock", e);
        loadMockData();
        setUsingMock(true); 
      }
    } else {
      loadMockData();
      setUsingMock(true);
    }
    setLoading(false);
  };

  const loadMockData = () => {
    setMembers(INITIAL_MEMBERS);
    setMeetingStatus(INITIAL_MEETING_STATUS);
    setPrayerRecords(INITIAL_PRAYER_RECORDS);
    // Even for mock data, apply cleaning logic for consistency
    const cleanedMockRecords = cleanAttendanceData(INITIAL_ATTENDANCE, INITIAL_MEETING_STATUS);
    setRecords(cleanedMockRecords);

    // Derive groups for mock data
    const mockGroups = Array.from(new Set(INITIAL_MEMBERS.map(m => m.group))).sort();
    setGroups(mockGroups);
  };

  useEffect(() => {
    loadData();
  }, []);

  // Shared Logic to toggle attendance
  const toggleAttendance = (memberId: string, date: string, type: AttendanceType) => {
    // Check if meeting is canceled first
    const isCanceled = meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
    if (isCanceled) return;

    // Optimistic UI Update
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === date);
      let updatedRecord: AttendanceRecord | null = null;
      let newTypes: AttendanceType[] = [];

      if (existing) {
        newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        updatedRecord = { ...existing, types: newTypes };

        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: existing.types.includes(type) ? false : true 
        });

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id);
        }
        return prev.map(r => r.id === existing.id ? updatedRecord! : r);
      } else {
        updatedRecord = {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: date,
          types: [type]
        };
        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: true 
        });
        return [...prev, updatedRecord];
      }
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-slate-500">데이터를 불러오는 중입니다...</p>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout>
        {usingMock && (
          <div className="bg-amber-50 border-b border-amber-200 px-4 py-2 text-xs text-amber-700 text-center">
            현재 <strong>데모 데이터</strong>를 보고 있습니다. 실제 스프레드시트와 연결하려면 [데이터 관리 {'>'} DB 연결 설정]을 이용하세요.
          </div>
        )}
        <Routes>
          <Route path="/" element={<Dashboard members={activeMembers} records={records} />} />
          <Route 
            path="/attendance" 
            element={
              <AttendanceMatrix 
                members={activeMembers} 
                records={records} 
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route 
            path="/prayer" 
            element={
              <PrayerRequests 
                members={activeMembers} 
                prayerRecords={prayerRecords} 
                availableGroups={groups}
              />
            } 
          />
          <Route 
            path="/profile" 
            element={
              <IndividualProfile 
                members={activeMembers} 
                records={records} 
                prayerRecords={prayerRecords}
                meetingStatus={meetingStatus}
                availableGroups={groups}
              />
            } 
          />
          <Route 
            path="/manage" 
            element={
              <DataManagement 
                members={members} 
                setMembers={setMembers} 
                records={records}
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
                refreshData={loadData}
                // @ts-ignore: Prop drilling for export functionality
                prayerRecords={prayerRecords} 
              />
            } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

