                    <td rowSpan={3} className="px-4 py-3 border border-slate-200">
                      <div className="font-semibold text-slate-700">{member.group}</div>
                    </td>
                    <td className="px-2 py-2 text-center text-xs font-bold text-blue-600 border border-slate-200 bg-blue-50">예배</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Worship, 'text-blue-600', 'hover:bg-blue-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Worship)}
                    </td>
                  </tr>

                  {/* Row 2: Gathering */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-indigo-600 border border-slate-200 bg-indigo-50">집회</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Gathering, 'text-indigo-600', 'hover:bg-indigo-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Gathering)}
                    </td>
                  </tr>

                  {/* Row 3: Wool */}
                  <tr className="bg-white border-b hover:bg-slate-50">
                    <td className="px-2 py-2 text-center text-xs font-bold text-emerald-600 border border-slate-200 bg-emerald-50">울</td>
                    {currentMonthSundays.map(date => 
                      renderCell(member.id, date, AttendanceType.Wool, 'text-emerald-600', 'hover:bg-emerald-50')
                    )}
                    <td className="px-2 py-2 text-center font-bold text-slate-700 border border-slate-200 bg-slate-50">
                      {calculateTotal(member.id, AttendanceType.Wool)}
                    </td>
                  </tr>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AttendanceMatrix;

import React, { useState, useMemo } from 'react';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from '../types';
import { Search, User, Phone, Briefcase, Calendar, Quote, Check, X, TrendingUp, AlertCircle, FileText, StickyNote } from 'lucide-react';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip as RechartsTooltip } from 'recharts';
import { SUNDAYS_2026 } from '../services/mockData';

interface IndividualProfileProps {
  members: Member[];
  records: AttendanceRecord[];
  prayerRecords: PrayerRecord[];
  meetingStatus: MeetingStatus[];
  availableGroups: string[];
}

const IndividualProfile: React.FC<IndividualProfileProps> = ({ members, records, prayerRecords, meetingStatus, availableGroups }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [selectedMemberId, setSelectedMemberId] = useState('');

  // 1. Resolve Target Member
  const targetMember = useMemo(() => {
    if (selectedMemberId) {
      return members.find(m => m.id === selectedMemberId) || null;
    }
    return null;
  }, [selectedMemberId, members]);

  // 2. Filter Members for Dropdown based on Group
  const filteredMembers = useMemo(() => {
    if (!selectedGroup) return [];
    return members.filter(m => m.group === selectedGroup).sort((a, b) => a.name.localeCompare(b.name));
  }, [selectedGroup, members]);

  // 3. Search Handler
  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setSearchQuery(val);

    // Clear dropdowns if typing
    if (val) {
      setSelectedGroup('');
      setSelectedMemberId('');

      // Auto-select if perfect match and unique
      const matched = members.filter(m => m.name.toLowerCase() === val.toLowerCase());
      if (matched.length === 1) {
        setSelectedMemberId(matched[0].id);
      }
    }
  };

  const handleGroupChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedGroup(e.target.value);
    setSelectedMemberId('');
    setSearchQuery('');
  };

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
    setSearchQuery('');
  };

  // 4. Calculate Statistics for Target Member (UPDATED LOGIC)
  const stats = useMemo(() => {
    if (!targetMember) return null;

    // Determine "Today" relative to the dataset year (2026)
    // If the actual current date is in a previous year (e.g., 2025), we simulate "Today" as 2026 for the demo.
    const now = new Date();
    const targetDate = new Date(2026, now.getMonth(), now.getDate()); 
    // If we are actually in 2026 or later, use the real date. If we are testing in 2025, use the mapped 2026 date.
    const comparisonDate = now.getFullYear() >= 2026 ? now : targetDate;

    // 1. Filter Sundays that have passed so far
    const passedSundays = SUNDAYS_2026.filter(d => new Date(d) <= comparisonDate);

    // 2. Calculate Total Possible Attendance (Denominator) excluding Canceled Meetings
    let possibleWorship = 0;
    let possibleGathering = 0;
    let possibleWool = 0;

    passedSundays.forEach(date => {
      // Check if meetings were canceled on this specific date
      const wCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Worship && s.isCanceled);
      const gCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Gathering && s.isCanceled);
      const lCanceled = meetingStatus.some(s => s.date === date && s.type === AttendanceType.Wool && s.isCanceled);

      if (!wCanceled) possibleWorship++;
      if (!gCanceled) possibleGathering++;
      if (!lCanceled) possibleWool++;
    });

    // 3. Calculate Actual Attendance (Numerator) for passed dates only
    const myRecords = records.filter(r => r.memberId === targetMember.id && passedSundays.includes(r.date));

    const worshipCount = myRecords.filter(r => r.types.includes(AttendanceType.Worship)).length;
    const gatheringCount = myRecords.filter(r => r.types.includes(AttendanceType.Gathering)).length;
    const woolCount = myRecords.filter(r => r.types.includes(AttendanceType.Wool)).length;

    const prayerCount = prayerRecords.filter(r => r.memberId === targetMember.id).length;

    // Helper for safe division
    const calcRate = (count: number, total: number) => total === 0 ? 0 : Math.round((count / total) * 100);

    return {
      worshipCount,
      gatheringCount,
      woolCount,
      prayerCount,
      possibleWorship,
      possibleGathering,
      possibleWool,
      worshipRate: calcRate(worshipCount, possibleWorship),
      gatheringRate: calcRate(gatheringCount, possibleGathering),
      woolRate: calcRate(woolCount, possibleWool),
      passedWeeksCount: passedSundays.length
    };
  }, [targetMember, records, prayerRecords, meetingStatus]);

  // 5. Radar Chart Data
  const radarData = useMemo(() => {
    if (!stats) return [];
    return [
      { subject: '예배', A: stats.worshipRate, fullMark: 100 },
      { subject: '집회', A: stats.gatheringRate, fullMark: 100 },
      { subject: '울모임', A: stats.woolRate, fullMark: 100 },
      // Arbitrary calculation for Prayer "Consistency" for visualization (e.g. max 20 requests/year = 100%)
      { subject: '기도', A: Math.min((stats.prayerCount / 20) * 100, 100), fullMark: 100 }, 
      { subject: '성실도', A: Math.round((stats.worshipRate + stats.woolRate + stats.gatheringRate) / 3), fullMark: 100 },
    ];
  }, [stats]);

  // 6. Member Prayer History
  const myPrayerHistory = useMemo(() => {
    if (!targetMember) return [];
    return prayerRecords
      .filter(r => r.memberId === targetMember.id)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [targetMember, prayerRecords]);

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-bold text-slate-800">개인별 종합 현황</h2>
        <p className="text-slate-500">개인의 출석 현황, 통계, 기도제목을 한눈에 확인합니다.</p>
      </header>

      {/* Search & Filter Section */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
           {/* Direct Search */}
           <div className="col-span-12 md:col-span-5">
             <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center text-indigo-700">
                <Search size={14} className="mr-1" /> 이름 검색
             </label>
             <div className="relative">
                <input 
                  type="text" 
                  className="w-full border border-indigo-200 rounded-lg pl-10 pr-4 py-2.5 text-sm focus:ring-indigo-500 focus:border-indigo-500 bg-indigo-50/30"
                  placeholder="성도 이름 입력..."
                  value={searchQuery}
                  onChange={handleSearch}
                />
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-indigo-400">
                  <Search size={18} />
                </div>
                {/* Search Suggestions */}
                {searchQuery && !targetMember && (
                  <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg mt-1 max-h-48 overflow-auto">
                    {members.filter(m => m.name.toLowerCase().includes(searchQuery.toLowerCase())).map(m => (
                      <div 
                        key={m.id} 
                        className="px-4 py-2 hover:bg-slate-50 cursor-pointer text-sm flex justify-between"
                        onClick={() => {
                          setSearchQuery('');
                          setSelectedGroup(m.group);
                          setSelectedMemberId(m.id);
                        }}
                      >
                        <span className="font-bold text-slate-700">{m.name}</span>
                        <span className="text-slate-400 text-xs">{m.group}</span>
                      </div>
                    ))}
                    {members.filter(m => m.name.toLowerCase().includes(searchQuery.toLowerCase())).length === 0 && (
                      <div className="px-4 py-2 text-sm text-slate-400">검색 결과가 없습니다.</div>
                    )}
                  </div>
                )}
             </div>
           </div>

           <div className="col-span-12 md:col-span-1 flex justify-center pb-2 text-slate-300 font-bold text-sm">OR</div>

           {/* Dropdowns */}
           <div className="col-span-12 md:col-span-6 flex gap-3">
              <div className="flex-1">
                 <label className="block text-xs font-bold text-slate-500 mb-2">소그룹 선택</label>
                 <select
                   className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
                   value={selectedGroup}
                   onChange={handleGroupChange}
                 >
                   <option value="">소그룹 선택</option>
                   {availableGroups.map(g => (
                     <option key={g} value={g}>{g}</option>
                   ))}
                 </select>
              </div>
              <div className="flex-1">
                 <label className="block text-xs font-bold text-slate-500 mb-2">멤버 선택</label>
                 <select
                   className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-400"
                   value={selectedMemberId}
                   onChange={handleMemberChange}
                   disabled={!selectedGroup}
                 >
                   <option value="">멤버를 선택하세요</option>
                   {filteredMembers.map(m => (
                     <option key={m.id} value={m.id}>{m.name}</option>
                   ))}
                 </select>
              </div>
           </div>
        </div>
      </div>

      {targetMember && stats ? (
        <>
          {/* Top Section: Profile & Analytics */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
             {/* Profile Card */}
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="bg-gradient-to-r from-indigo-500 to-purple-600 h-24 relative">
                   <div className="absolute -bottom-10 left-6 w-20 h-20 rounded-full bg-white p-1 shadow-md">
                      <div className="w-full h-full rounded-full bg-slate-200 flex items-center justify-center text-slate-500 text-2xl font-bold">
                        {targetMember.name.substring(0, 1)}
                      </div>
                   </div>
                </div>
                <div className="pt-12 pb-6 px-6">
                   <h3 className="text-2xl font-bold text-slate-800">{targetMember.name}</h3>
                   <p className="text-indigo-600 font-medium">{targetMember.group}</p>

                   <div className="mt-6 space-y-3">
                      <div className="flex items-center text-sm text-slate-600">
                         <User size={16} className="mr-3 text-slate-400" />
                         <span>{targetMember.role || '성도'}</span>
                      </div>
                      <div className="flex items-center text-sm text-slate-600">
                         <Phone size={16} className="mr-3 text-slate-400" />
                         <span>{targetMember.phoneNumber || '연락처 없음'}</span>
                      </div>
                      {targetMember.specialNotes && (
                        <div className="flex items-start text-sm text-slate-700 bg-slate-100 p-3 rounded-lg mt-2 border border-slate-200">
                           <StickyNote size={16} className="mr-2 mt-0.5 flex-shrink-0 text-slate-500" />
                           <div className="flex-1">
                              <span className="font-bold text-xs text-slate-500 block mb-1">비고 (Memo)</span>
                              <span>{targetMember.specialNotes}</span>
                           </div>
                        </div>
                      )}

                      <div className="pt-4 border-t border-slate-100 text-xs text-slate-400">
                        * 통계 기준: 1월 1일 ~ 오늘 ({stats.passedWeeksCount}주 경과)
                      </div>
                   </div>
                </div>
             </div>

             {/* Stats Cards & Chart */}
             <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h4 className="font-bold text-slate-700 mb-4 flex items-center justify-between">
                   <span className="flex items-center"><TrendingUp size={18} className="mr-2 text-indigo-500" /> 출석 및 신앙 생활 분석</span>
                   <span className="text-xs font-normal text-slate-400 bg-slate-50 px-2 py-1 rounded">모임 취소일 제외 계산</span>
                </h4>

                <div className="flex flex-col md:flex-row gap-6 h-full">
                   {/* Stats Grid */}
                   <div className="flex-1 grid grid-cols-2 gap-4">
                      <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex flex-col justify-center">
                         <span className="text-xs font-bold text-blue-600 uppercase">예배 출석률</span>
                         <div className="flex items-end mt-1">
                            <span className="text-2xl font-bold text-slate-800">{stats.worshipRate}%</span>
                            <span className="text-xs text-slate-500 ml-2 mb-1">({stats.worshipCount}/{stats.possibleWorship}회)</span>
                         </div>
                      </div>
                      <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100 flex flex-col justify-center">
                         <span className="text-xs font-bold text-indigo-600 uppercase">집회 출석률</span>
                         <div className="flex items-end mt-1">
                            <span className="text-2xl font-bold text-slate-800">{stats.gatheringRate}%</span>
                            <span className="text-xs text-slate-500 ml-2 mb-1">({stats.gatheringCount}/{stats.possibleGathering}회)</span>
                         </div>
                      </div>
                      <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100 flex flex-col justify-center">
                         <span className="text-xs font-bold text-emerald-600 uppercase">울모임 출석률</span>
                         <div className="flex items-end mt-1">
                            <span className="text-2xl font-bold text-slate-800">{stats.woolRate}%</span>
                            <span className="text-xs text-slate-500 ml-2 mb-1">({stats.woolCount}/{stats.possibleWool}회)</span>
                         </div>
                      </div>
                      <div className="bg-amber-50 p-4 rounded-xl border border-amber-100 flex flex-col justify-center">
