           -
        </td>
      );
    }

    return (
      <td 
        key={`${memberId}-${date}-${type}`} 
        onClick={() => onToggleAttendance(memberId, date, type)}
        className={`px-1 py-1 md:px-2 md:py-2 border border-slate-200 text-center cursor-pointer transition-colors ${hoverClass}`}
      >
      </td>
    );
  };

