// Full Google Apps Script Code
const GAS_CODE_SNIPPET = `
/* 
  Church Attendance Admin - Google Apps Script Backend
  Copy this entire code into Code.gs in your Google Apps Script project.
*/

// --- CONFIGURATION ---
const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
const SHEET_MEMBERS = "Members";
const SHEET_ATTENDANCE = "Attendance";
const SHEET_PRAYERS = "Prayers";
const SHEET_CONFIG = "SessionConfig"; // For MeetingStatus

// --- MAIN HANDLERS ---

function doGet(e) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);

    // 1. Members
    const memSheet = ss.getSheetByName(SHEET_MEMBERS);
    let members = [];
    if (memSheet) {
      const rows = memSheet.getDataRange().getValues();
      // Assume Row 1 is header
      for (let i = 1; i < rows.length; i++) {
        const r = rows[i];
        if (r[0]) { // Check ID
          members.push({
            id: String(r[0]),
            name: String(r[1]),
            group: String(r[2]),
            wool: String(r[3] || r[2]),
            phoneNumber: String(r[4] || ''),
            role: String(r[5] || '성도'),
            status: String(r[6] || 'ACTIVE'),
            specialNotes: String(r[7] || '')
          });
        }
      }
    }

    // 2. Attendance
    const attSheet = ss.getSheetByName(SHEET_ATTENDANCE);
    let attendance = [];
    if (attSheet) {
      const rows = attSheet.getDataRange().getValues();
      for (let i = 1; i < rows.length; i++) {
        const r = rows[i];
        if (r[0] && r[1]) {
          // r[3] might be JSON string of types or comma separated
          let types = [];
          if (r[3]) {
            try {
              types = JSON.parse(r[3]);
            } catch(e) {
              types = String(r[3]).split(',').map(s=>s.trim());
            }
          }
          attendance.push({
            id: String(r[0]),
            memberId: String(r[1]),
            date: formatDate(r[2]),
            types: types
          });
        }
      }
    }

    // 3. Prayers
    const praySheet = ss.getSheetByName(SHEET_PRAYERS);
    let prayers = [];
    if (praySheet) {
      const rows = praySheet.getDataRange().getValues();
      for (let i = 1; i < rows.length; i++) {
        const r = rows[i];
        if (r[0]) {
          prayers.push({
            id: String(r[0]),
            memberId: String(r[1]),
            date: formatDate(r[2]),
            content: String(r[3] || ''),
            note: String(r[4] || '')
          });
        }
      }
    }

    // 4. Meeting Status (Config)
    const confSheet = ss.getSheetByName(SHEET_CONFIG);
    let meetingStatus = [];
    if (confSheet) {
      const rows = confSheet.getDataRange().getValues();
      // Expected: Date | Type | IsCanceled | EventName
      for (let i = 1; i < rows.length; i++) {
        const r = rows[i];
        if (r[0]) {
          meetingStatus.push({
            date: formatDate(r[0]),
            type: String(r[1]),
            isCanceled: r[2] === true || String(r[2]).toLowerCase() === 'true',
            event: String(r[3] || '')
          });
        }
      }
    }

    // Groups (Unique from members)
    const groups = [...new Set(members.map(m => m.group))].sort();

    return ContentService.createTextOutput(JSON.stringify({
      status: 'success',
      members: members,
      attendance: attendance,
      prayers: prayers,
      meetingStatus: meetingStatus,
      groups: groups
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: err.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const postData = JSON.parse(e.postData.contents);
    const action = postData.action;
    const payload = postData.payload;
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);

    if (action === 'UPDATE_ATTENDANCE') {
      const sheet = getOrCreateSheet(ss, SHEET_ATTENDANCE, ['ID', 'MemberID', 'Date', 'Types']);
      const data = sheet.getDataRange().getValues();
      const memberId = payload.memberId;
      const date = payload.date; // YYYY-MM-DD
      const type = payload.type;
      const isAdd = payload.isAdd;

      let foundRowIndex = -1;
      let existingRecord = null;
      let existingTypes = [];

      // Search matching record
      for (let i = 1; i < data.length; i++) {
        // Need to parse date comparison carefully
        const rowDate = formatDate(data[i][2]);
        if (String(data[i][1]) === memberId && rowDate === date) {
          foundRowIndex = i + 1; // 1-based index
          existingRecord = data[i];
          try { existingTypes = JSON.parse(data[i][3]); } catch(e) { existingTypes = []; }
          break;
        }
      }

      if (foundRowIndex > -1) {
        // Update existing
        const setTypes = new Set(existingTypes);
        if (isAdd) setTypes.add(type);
        else setTypes.delete(type);

        const newTypes = Array.from(setTypes);
        if (newTypes.length === 0) {
          // Remove row if empty
          sheet.deleteRow(foundRowIndex);
        } else {
          sheet.getRange(foundRowIndex, 4).setValue(JSON.stringify(newTypes));
        }
      } else {
        // Create new
        if (isAdd) {
          const newId = 'a-' + new Date().getTime();
          sheet.appendRow([newId, memberId, date, JSON.stringify([type])]);
        }
      }
    } 
    else if (action === 'ADD_MEMBER') {
       const sheet = getOrCreateSheet(ss, SHEET_MEMBERS, ['ID', 'Name', 'Group', 'Wool', 'Phone', 'Role', 'Status', 'Memo']);
       sheet.appendRow([
         payload.id, 
         payload.name, 
         payload.group, 
         payload.wool, 
         payload.phoneNumber, 
         payload.role, 
         payload.status, 
         payload.specialNotes
       ]);
    }
    else if (action === 'UPDATE_MEMBER') {
       const sheet = ss.getSheetByName(SHEET_MEMBERS);
       const data = sheet.getDataRange().getValues();
       for(let i=1; i<data.length; i++) {
         if(String(data[i][0]) === payload.id) {
           // Update columns
           const row = i + 1;
           sheet.getRange(row, 2).setValue(payload.name);
           sheet.getRange(row, 3).setValue(payload.group);
           sheet.getRange(row, 4).setValue(payload.wool || payload.group);
           sheet.getRange(row, 5).setValue(payload.phoneNumber);
           sheet.getRange(row, 7).setValue(payload.status);
           sheet.getRange(row, 8).setValue(payload.specialNotes);
           break;
         }
       }
    }

    return ContentService.createTextOutput(JSON.stringify({ status: 'success' }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- HELPERS ---
function formatDate(dateObj) {
  if (!dateObj) return "";
  if (typeof dateObj === 'string') {
    // Already string, assume YYYY-MM-DD or standard ISO
    return dateObj.substring(0, 10);
  }
  try {
    const y = dateObj.getFullYear();
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const d = String(dateObj.getDate()).padStart(2, '0');
    return \`\${y}-\${m}-\${d}\`;
  } catch (e) {
    return String(dateObj);
  }
}

function getOrCreateSheet(ss, name, headers) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (headers) sheet.appendRow(headers);
  }
  return sheet;
}
`;

interface DataManagementProps {
  members: Member[];
  setMembers: React.Dispatch<React.SetStateAction<Member[]>>;
  records: AttendanceRecord[];
  meetingStatus: MeetingStatus[];
  availableGroups: string[];
  onToggleAttendance: (memberId: string, date: string, type: AttendanceType) => void;
  refreshData: () => void;
  prayerRecords?: PrayerRecord[];
}

const DataManagement: React.FC<DataManagementProps> = ({ 
  members, 
  setMembers, 
  records, 
  meetingStatus, 
  availableGroups, 
  onToggleAttendance, 
  refreshData, 
  prayerRecords = [] 
}) => {
  const [activeTab, setActiveTab] = useState<'members' | 'attendance' | 'settings' | 'export'>('members');
  const [editingMember, setEditingMember] = useState<Member | null>(null);
  const [deletingMember, setDeletingMember] = useState<Member | null>(null); // For delete confirmation

  // Settings State
  const [scriptUrl, setLocalScriptUrl] = useState(getScriptUrl() || DEFAULT_SCRIPT_URL);
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);

  // New Member State
  const [newMember, setNewMember] = useState<Partial<Member>>({ group: '', name: '', phoneNumber: '', specialNotes: '' });
  const [isAddingMember, setIsAddingMember] = useState(false);
  const [showAddSuccess, setShowAddSuccess] = useState(false);

  // Sorting & Filtering State
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(null);
  const [memberFilterGroup, setMemberFilterGroup] = useState<string>('all');
  const [memberSearchQuery, setMemberSearchQuery] = useState<string>('');

  const [attendanceFilterGroup, setAttendanceFilterGroup] = useState<string>('all');
  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());

  // Export State
  const [exportStartDate, setExportStartDate] = useState<string>('2026-01-01');
  const [exportEndDate, setExportEndDate] = useState<string>('2026-12-31');

  // Update selected date if tab changes to attendance or on mount
  useEffect(() => {
    if (activeTab === 'attendance') {
      setSelectedDate(getClosestSunday());
    }
  }, [activeTab]);

  // Helper to get event name for selected date in Attendance tab
  const getEventName = (date: string) => {
    return meetingStatus.find(s => s.date === date)?.event || '';
  };

  const handleUpdateMember = (id: string, field: keyof Member, value: string) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, [field]: value } : m));
  };

  const handleAddMember = async () => {
    if (!newMember.name || !newMember.group) {
        alert("이름과 소그룹을 모두 입력해주세요.");
        return;
    }

    setIsAddingMember(true);

    // Generate Unique ID: M + 4 random digits
    let id = '';
    let isUnique = false;
    while (!isUnique) {
      const random = Math.floor(1000 + Math.random() * 9000); // 1000-9999
      id = `M${random}`;
      if (!members.some(m => m.id === id)) {
        isUnique = true;
      }
    }

    const memberToAdd: Member = { 
      id, 
      name: newMember.name!, 
      group: newMember.group!, 
      wool: newMember.group!,
      phoneNumber: newMember.phoneNumber || '',
      role: 'MEMBER', 
      status: 'ACTIVE', 
      latestPrayerRequest: '', 
      specialNotes: newMember.specialNotes || '' 
    };

    try {
      // 1. Send to Google Sheets
      await sendAction('ADD_MEMBER', memberToAdd);

      // 2. Update Local State (Optimistic)
      setMembers(prev => [...prev, memberToAdd]);

      // 3. Reset Form & Show Success
      setNewMember({ group: '', name: '', phoneNumber: '', specialNotes: '' });
      setShowAddSuccess(true);
    } catch (e) {
      alert("멤버 추가 중 오류가 발생했습니다.");
    } finally {
      setIsAddingMember(false);
    }
  };

  const handleSaveEdit = async () => {
    if (!editingMember) return;
    setIsAddingMember(true); // Reuse loading state

    try {
      // Update in Google Sheets
      await sendAction('UPDATE_MEMBER', editingMember);

      // Update Local State
      setMembers(prev => prev.map(m => m.id === editingMember.id ? editingMember : m));
      setEditingMember(null);
    } catch (e) {
      alert("정보 수정 중 오류가 발생했습니다.");
    } finally {
      setIsAddingMember(false);
    }
  };

  const handleDeleteMember = async () => {
    if (!deletingMember) return;
    setIsAddingMember(true); // Reuse loading state

    try {
      // Soft Delete: Set status to INACTIVE
      const inactiveMember = { ...deletingMember, status: 'INACTIVE' };
      await sendAction('UPDATE_MEMBER', inactiveMember);

      // Update Local State: Do NOT remove, just update status
      setMembers(prev => prev.map(m => m.id === deletingMember.id ? inactiveMember : m));
      setDeletingMember(null);
    } catch (e) {
      alert("삭제 중 오류가 발생했습니다.");
    } finally {
      setIsAddingMember(false);
    }
  };

  const handleSort = (key: string) => {
    setSortConfig(current => {
      let direction: 'asc' | 'desc' = 'asc';
      if (current && current.key === key) {
        direction = current.direction === 'asc' ? 'desc' : 'asc';
      }
      return { key, direction };
    });
  };

  // Sort and Filter for Member Management Tab
  const processedMembers = useMemo(() => {
    let items = [...members];

    // Filter by Group
    if (memberFilterGroup !== 'all') {
      items = items.filter(m => m.group === memberFilterGroup);
    }

    // Filter by Name Search
    if (memberSearchQuery.trim()) {
      items = items.filter(m => m.name.toLowerCase().includes(memberSearchQuery.toLowerCase()));
    }

    // Sort
    if (sortConfig && activeTab === 'members') {
      items.sort((a, b) => {
        // @ts-ignore
