import DataManagement from './components/DataManagement';
import IndividualProfile from './components/IndividualProfile';
import { INITIAL_MEMBERS, INITIAL_ATTENDANCE, INITIAL_PRAYER_RECORDS, INITIAL_MEETING_STATUS } from './services/mockData';
import { fetchSheetData, sendAction, getScriptUrl } from './services/sheetService';
import { Member, AttendanceRecord, PrayerRecord, AttendanceType, MeetingStatus } from './types';
import { Lock } from 'lucide-react';

const App: React.FC = () => {
  // Global State
  const [members, setMembers] = useState<Member[]>([]);
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [prayerRecords, setPrayerRecords] = useState<PrayerRecord[]>([]);
  const [meetingStatus, setMeetingStatus] = useState<MeetingStatus[]>([]);
  const [groups, setGroups] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMock, setUsingMock] = useState(false);

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputPassword, setInputPassword] = useState('');
  const [loginError, setLoginError] = useState('');
  const [validAccessCodes, setValidAccessCodes] = useState<string[]>([]);

  // Filter only Active members for the app views (except DataManagement)
  const activeMembers = useMemo(() => {
    return members.filter(m => m.status !== 'INACTIVE');
  }, [members]);

  // Function to clean attendance records based on meeting status
  // This ensures that if a meeting is canceled (FALSE in DB), any accidental 'Present' record is ignored.
  const cleanAttendanceData = (rawRecords: AttendanceRecord[], rawStatus: MeetingStatus[]): AttendanceRecord[] => {
    return rawRecords.map(record => {
      // Filter out types that are marked as canceled in the meeting status
      const validTypes = record.types.filter(type => {
        const statusForDateAndType = rawStatus.find(s => s.date === record.date && s.type === type);
        // If status exists and isCanceled is true, drop this attendance type
        if (statusForDateAndType && statusForDateAndType.isCanceled) {
          return false;
        }
        return true;
      });

      return { ...record, types: validTypes };
    }).filter(record => record.types.length > 0); // Remove records that became empty
  };

  // Load data function
  const loadData = async () => {
    setLoading(true);
    const scriptUrl = getScriptUrl();

    // With the new auto-connect logic, scriptUrl should be the default one if not set locally
    if (scriptUrl) {
      try {
        const data = await fetchSheetData();

        const fetchedMembers = data.members || [];
        const fetchedMeetingStatus = data.meetingStatus || [];
        const fetchedRecords = data.attendance || [];
        const fetchedPrayers = data.prayers || [];
        const fetchedAccessCodes = data.accessCodes || [];

        // 1. Set Basic Data
        setMembers(fetchedMembers);
        setMeetingStatus(fetchedMeetingStatus);
        setPrayerRecords(fetchedPrayers);
        setValidAccessCodes(fetchedAccessCodes);

        // 2. Clean Attendance Records (Requirement 1: Strict consistency)
        const cleanedRecords = cleanAttendanceData(fetchedRecords, fetchedMeetingStatus);
        setRecords(cleanedRecords);

        // If groups are returned from API, use them. Otherwise derive from members.
        if (data.groups && data.groups.length > 0) {
          setGroups(data.groups);
        } else {
          const derivedGroups = Array.from(new Set(fetchedMembers.map(m => m.group))).sort();
          setGroups(derivedGroups);
        }

        setUsingMock(false);
      } catch (e) {
        console.error("Failed to load live data, falling back to mock", e);
        loadMockData();
        setUsingMock(true); 
      }
    } else {
      loadMockData();
      setUsingMock(true);
    }
    setLoading(false);
  };

  const loadMockData = () => {
    setMembers(INITIAL_MEMBERS);
    setMeetingStatus(INITIAL_MEETING_STATUS);
    setPrayerRecords(INITIAL_PRAYER_RECORDS);
    // Even for mock data, apply cleaning logic for consistency
    const cleanedMockRecords = cleanAttendanceData(INITIAL_ATTENDANCE, INITIAL_MEETING_STATUS);
    setRecords(cleanedMockRecords);

    // Derive groups for mock data
    const mockGroups = Array.from(new Set(INITIAL_MEMBERS.map(m => m.group))).sort();
    setGroups(mockGroups);

    // Set a default mock access code for demo purposes (fallback)
    setValidAccessCodes(['18870691']); 
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // Master password override: 18870691
    if (inputPassword.trim() === '18870691' || validAccessCodes.includes(inputPassword.trim())) {
      setIsAuthenticated(true);
      setLoginError('');
    } else {
      setLoginError('비밀번호가 올바르지 않습니다.');
    }
  };

  // Shared Logic to toggle attendance
  const toggleAttendance = (memberId: string, date: string, type: AttendanceType) => {
    // Check if meeting is canceled first
    const isCanceled = meetingStatus.some(s => s.date === date && s.type === type && s.isCanceled);
    if (isCanceled) return;

    // Optimistic UI Update
    setRecords(prev => {
      const existing = prev.find(r => r.memberId === memberId && r.date === date);
      let updatedRecord: AttendanceRecord | null = null;
      let newTypes: AttendanceType[] = [];

      if (existing) {
        newTypes = existing.types.includes(type)
          ? existing.types.filter(t => t !== type)
          : [...existing.types, type];

        updatedRecord = { ...existing, types: newTypes };

        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: existing.types.includes(type) ? false : true 
        });

        if (newTypes.length === 0) {
          return prev.filter(r => r.id !== existing.id);
        }
        return prev.map(r => r.id === existing.id ? updatedRecord! : r);
      } else {
        updatedRecord = {
          id: `a-${Date.now()}-${Math.random()}`,
          memberId,
          date: date,
          types: [type]
        };
        // Sync with DB
        sendAction('UPDATE_ATTENDANCE', { 
            memberId, date, type, 
            isAdd: true 
        });
        return [...prev, updatedRecord];
      }
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-slate-500">데이터를 불러오는 중입니다...</p>
        </div>
      </div>
    );
  }

  // Login Screen
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow-lg max-w-md w-full p-8">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 text-indigo-600">
              <Lock size={32} />
            </div>
            <h1 className="text-2xl font-bold text-slate-800">관리자 로그인</h1>
            <p className="text-slate-500 mt-2">소그룹 출석부 접근을 위해<br/>접속 코드를 입력해주세요.</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <input 
                type="password" 
                className="w-full border border-slate-300 rounded-lg p-3 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all text-center tracking-widest text-lg"
                placeholder="비밀번호 입력"
                value={inputPassword}
                onChange={(e) => setInputPassword(e.target.value)}
                autoFocus
              />
              {loginError && <p className="text-rose-500 text-sm mt-2 text-center">{loginError}</p>}
            </div>
            <button 
              type="submit" 
              className="w-full bg-indigo-600 text-white py-3 rounded-lg font-bold hover:bg-indigo-700 transition-colors shadow-md active:scale-[0.98] transform"
            >
              확인
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout>
        {usingMock && (
          <div className="bg-amber-50 border-b border-amber-200 px-4 py-2 text-xs text-amber-700 text-center">
            현재 <strong>설정/데모 모드</strong>입니다. <strong>[데이터 관리 &gt; DB 연결 설정]</strong>에서 스크립트를 업데이트하고 연결하세요.
          </div>
        )}
        <Routes>
          <Route path="/" element={<Dashboard members={activeMembers} records={records} meetingStatus={meetingStatus} />} />
          <Route 
            path="/attendance" 
            element={
              <AttendanceMatrix 
                members={activeMembers} 
                records={records} 
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
              />
            } 
          />
          <Route 
            path="/prayer" 
            element={
              <PrayerRequests 
                members={activeMembers} 
                prayerRecords={prayerRecords} 
                availableGroups={groups}
              />
            } 
          />
          <Route 
            path="/profile" 
            element={
              <IndividualProfile 
                members={activeMembers} 
                records={records} 
                prayerRecords={prayerRecords}
                meetingStatus={meetingStatus}
                availableGroups={groups}
              />
            } 
          />
          <Route 
            path="/manage" 
            element={
              <DataManagement 
                members={members} 
                setMembers={setMembers} 
                records={records}
                meetingStatus={meetingStatus}
                availableGroups={groups}
                onToggleAttendance={toggleAttendance}
                refreshData={loadData}
                // @ts-ignore: Prop drilling for export functionality
                prayerRecords={prayerRecords} 
              />
            } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Member, PrayerRecord } from '../types';
import { Quote, AlertCircle, Calendar, User, Search, FileText, X } from 'lucide-react';
import { SUNDAYS_2026 } from '../services/mockData';
import { getClosestSunday } from '../services/utils';

interface PrayerRequestsProps {
  members: Member[];
  prayerRecords: PrayerRecord[];
  availableGroups: string[];
}

const PrayerRequests: React.FC<PrayerRequestsProps> = ({ members, prayerRecords, availableGroups }) => {
  const [viewMode, setViewMode] = useState<'member' | 'date'>('date');
  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());

  // Member View State
  const [selectedGroup, setSelectedGroup] = useState<string>('');
  const [selectedMemberId, setSelectedMemberId] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Initial load effect
  useEffect(() => {
    setSelectedDate(getClosestSunday());
  }, []);

  // Sort function to be reused
  const sortMembers = (a: Member, b: Member) => {
    // Priority: Leader -> Alphabetical

    // 1. Leader Check
    const roleA = (a.role || '').toString().toUpperCase().trim();
    const roleB = (b.role || '').toString().toUpperCase().trim();

    const isALeader = roleA === 'LEADER' || roleA === '리더';
    const isBLeader = roleB === 'LEADER' || roleB === '리더';

    if (isALeader && !isBLeader) return -1;
    if (!isALeader && isBLeader) return 1;

    // 2. Alphabetical Check
    const nameA = a.name.replace(/\*/g, '').trim();
    const nameB = b.name.replace(/\*/g, '').trim();

    return nameA.localeCompare(nameB);
  };

  // Filter members based on selected group (for dropdown)
  const membersInGroup = useMemo(() => {
    if (!selectedGroup) return [];
    return members
      .filter(m => m.group === selectedGroup)
      .sort(sortMembers);
  }, [members, selectedGroup]);

  // View 1: By Date - Group by Small Group/Wool directly (Flattened)
  const recordsByDate = useMemo(() => {
    const records = prayerRecords.filter(r => r.date === selectedDate);
    const groups: Record<string, { member: Member; record: PrayerRecord }[]> = {};

    members.forEach(member => {
       const record = records.find(r => r.memberId === member.id);
       if (!groups[member.group]) groups[member.group] = [];

       // UPDATED: Only show if there is an actual record for this date.
       // Do NOT show just because there is a member specialNote (memo)
       if (record) {
         groups[member.group].push({ member, record });
       }
    });
    return groups;
  }, [selectedDate, prayerRecords, members]);

  // Check if there are any records to display for the Empty State
  const hasAnyRecords = useMemo(() => {
    return Object.values(recordsByDate).some(items => items.length > 0);
  }, [recordsByDate]);

  // View 2: By Member - Search Query OR Single Member OR All in Group
  const memberHistoryData = useMemo(() => {
    let targetMembers: Member[] = [];

    // Priority 1: Search Query
    if (searchQuery.trim()) {
       const query = searchQuery.toLowerCase().trim();
       targetMembers = members.filter(m => m.name.toLowerCase().includes(query));
    }
    // Priority 2: Specific Member Selected via Dropdown
    else if (selectedMemberId) {
      const m = members.find(m => m.id === selectedMemberId);
      if (m) targetMembers = [m];
    } 
    // Priority 3: Group Selected
    else if (selectedGroup) {
      targetMembers = members
        .filter(m => m.group === selectedGroup)
        .sort(sortMembers);
    } 
    else {
      return null;
    }

    if (targetMembers.length === 0) return [];

    return targetMembers.map(member => {
       const myRecords = prayerRecords
        .filter(r => r.memberId === member.id)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
       return { member, records: myRecords };
    });
  }, [searchQuery, selectedMemberId, selectedGroup, members, prayerRecords]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setSearchQuery(val);
    if (val) {
      setSelectedGroup('');
      setSelectedMemberId('');
    }
  };

  const handleGroupChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedGroup(e.target.value);
    setSelectedMemberId(''); 
    setSearchQuery('');
  };

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
    setSearchQuery(''); 
  };

  return (
    <div className="space-y-6">
       <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">기도 제목 및 특이사항</h2>
          <p className="text-slate-500">
            {viewMode === 'date' 
              ? '매주 입력되는 기도제목과 특이사항을 소그룹/울별로 확인합니다.' 
              : '각 성도님의 기도제목 및 특이사항 히스토리를 확인합니다.'}
          </p>
        </div>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button
             onClick={() => setViewMode('date')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'date' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <Calendar size={16} className="mr-2" /> 날짜별 보기
           </button>
           <button
             onClick={() => setViewMode('member')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'member' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <User size={16} className="mr-2" /> 멤버별 보기
           </button>
        </div>
      </header>

      {viewMode === 'date' && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <label className="font-bold text-slate-700">날짜 선택:</label>
          <select
            className="border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
          >
            {SUNDAYS_2026.slice().reverse().map(d => ( 
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      )}

      {viewMode === 'member' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4 md:space-y-0 md:flex md:gap-6 items-end">
          <div className="flex-1 w-full">
            <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center text-indigo-700">
              <Search size={14} className="mr-1" /> 이름 직접 검색 (추천)
            </label>
            <div className="relative">
              <input 
                type="text" 
                className="w-full border border-indigo-200 rounded-lg pl-10 pr-4 py-2.5 text-sm focus:ring-indigo-500 focus:border-indigo-500 bg-indigo-50/30"
                placeholder="이름을 입력하세요 (예: 김철수)"
                value={searchQuery}
                onChange={handleSearchChange}
              />
              <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-indigo-400">
                <Search size={18} />
              </div>
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-400 hover:text-slate-600"
                >
                  <X size={16} />
                </button>
              )}
            </div>
          </div>

          <div className="hidden md:flex items-center justify-center pb-3 px-2 text-slate-300 font-bold text-sm">OR</div>
          <div className="md:hidden text-center text-xs text-slate-400 my-2">- 또는 소그룹으로 찾기 -</div>

          <div className="flex-1 w-full flex gap-3">
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">소그룹 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
                 value={selectedGroup}
                 onChange={handleGroupChange}
               >
                 <option value="">선택 안 함</option>
                 {availableGroups.map(g => (
                   <option key={g} value={g}>{g}</option>
                 ))}
               </select>
            </div>
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">멤버 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-400"
                 value={selectedMemberId}
                 onChange={handleMemberChange}
                 disabled={!selectedGroup}
               >
                 <option value="">전체 보기</option>
                 {membersInGroup.map(m => (
                   <option key={m.id} value={m.id}>{m.name}</option>
                 ))}
               </select>
            </div>
          </div>
        </div>
      )}

      {viewMode === 'date' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Object.entries(recordsByDate).map(([groupName, items]) => {
            const groupItems = items;
            if (groupItems.length === 0) return null;
            return (
               <div key={groupName} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                  <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                    <span className="w-2 h-2 bg-indigo-500 rounded-full mr-2"></span>
                    {groupName}
                  </h3>

                  <div className="space-y-4">
                    {groupItems.map(({ member, record }) => (
                      <div key={member.id} className="relative pl-4 border-l-2 border-slate-100 hover:border-indigo-300 transition-colors">
                        <div className="flex items-baseline justify-between">
                          <h4 className="font-semibold text-slate-800">{member.name}</h4>
                          {member.specialNotes && (
                            <span className="flex items-center text-xs text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-100 max-w-[50%] truncate">
                              <AlertCircle size={10} className="mr-1" />
                              {member.specialNotes}
                            </span>
                          )}
                        </div>

                        {/* Always show content since we filtered by record existence */}
                         <>
                           {record.content && (
                             <div className="mt-2 text-sm text-slate-600 flex items-start">
                               <Quote size={14} className="text-slate-300 mr-2 mt-1 flex-shrink-0" />
                               <p>{record.content}</p>
                             </div>
                           )}
                           {record.note && (
                             <div className="mt-2 text-sm text-slate-700 flex items-start bg-yellow-50 p-2 rounded border border-yellow-100">
                               <FileText size={14} className="text-yellow-600 mr-2 mt-0.5 flex-shrink-0" />
                               <p>{record.note}</p>
                             </div>
                           )}
                         </>
                      </div>
                    ))}
                  </div>
              </div>
            );
          })}
          {!hasAnyRecords && (
             <div className="col-span-full text-center py-12 text-slate-400">
               해당 날짜에 등록된 내용이 없습니다.
             </div>
          )}
        </div>
      )}

      {/* ... Member View ... */}
      {viewMode === 'member' && (
         <div className="space-y-6">
            {!memberHistoryData ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[400px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <Search size={48} className="mb-4 opacity-10" />
                  <p>위에서 이름을 검색하거나, 소그룹을 선택하여 기록을 확인하세요.</p>
               </div>
            ) : memberHistoryData.length === 0 ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[300px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <AlertCircle size={48} className="mb-4 opacity-10" />
                  <p>검색 결과가 없습니다.</p>
               </div>
            ) : (
               memberHistoryData.map(({ member, records }) => (
                 <div key={member.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="p-6 border-b border-slate-100 bg-slate-50/50">
                       <div className="flex justify-between items-start">
                          <div>
                             <h3 className="font-bold text-2xl text-slate-800">{member.name}</h3>
                             <p className="text-sm text-slate-500 mt-1">{member.group}</p>
                          </div>
                          {member.specialNotes && (
                             <div className="bg-rose-50 border border-rose-100 text-rose-600 px-4 py-2 rounded-lg max-w-md">
                                <p className="text-xs font-bold flex items-center mb-1">
                                   <AlertCircle size={12} className="mr-1" /> 기본 비고
                                </p>
                                <p className="text-sm">{member.specialNotes}</p>
                             </div>
                          )}
                       </div>
                    </div>

                    <div className="p-6">
                       <h4 className="text-sm font-bold text-slate-600 mb-4 uppercase tracking-wider">히스토리</h4>
                       <div className="space-y-6">
                          {records.length > 0 ? (
                             records.map(record => (
                                <div key={record.id} className="relative pl-6 border-l-2 border-indigo-100">
                                   <div className="absolute -left-[5px] top-1.5 w-2 h-2 rounded-full bg-indigo-500 ring-4 ring-white"></div>
                                   <span className="text-sm font-bold text-indigo-600 block mb-1">{record.date}</span>
                                   <div className="space-y-2">
                                       {record.content && (
                                         <div className="bg-slate-50 p-4 rounded-lg text-slate-700 text-sm leading-relaxed border border-slate-100">
                                            <div className="flex items-center text-xs text-slate-400 mb-1">
                                              <Quote size={12} className="mr-1"/> 기도제목
                                            </div>
                                            {record.content}
                                         </div>
                                       )}
                                       {record.note && (
                                         <div className="bg-yellow-50 p-3 rounded-lg text-slate-700 text-sm leading-relaxed border border-yellow-100">
                                            <div className="flex items-center text-xs text-yellow-600 mb-1 font-bold">
                                              <FileText size={12} className="mr-1"/> 특이사항
                                            </div>
                                            {record.note}
                                         </div>
                                       )}
                                   </div>
                                </div>
                             ))
                          ) : (
                             <div className="text-center py-4 text-slate-400 text-sm">
                                <p>등록된 이력이 없습니다.</p>
                             </div>
                          )}
                       </div>
                    </div>
                 </div>
               ))
            )}
         </div>
      )}
    </div>
  );
};

export default PrayerRequests;

import React, { useState, useMemo, useEffect } from 'react';
import { Member, PrayerRecord } from '../types';
import { Quote, AlertCircle, Calendar, User, Search, FileText, X } from 'lucide-react';
import { SUNDAYS_2026 } from '../services/mockData';
import { getClosestSunday } from '../services/utils';

interface PrayerRequestsProps {
  members: Member[];
  prayerRecords: PrayerRecord[];
  availableGroups: string[];
}

const PrayerRequests: React.FC<PrayerRequestsProps> = ({ members, prayerRecords, availableGroups }) => {
  const [viewMode, setViewMode] = useState<'member' | 'date'>('date');
  const [selectedDate, setSelectedDate] = useState<string>(getClosestSunday());

  // Member View State
  const [selectedGroup, setSelectedGroup] = useState<string>('');
  const [selectedMemberId, setSelectedMemberId] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Initial load effect
  useEffect(() => {
    setSelectedDate(getClosestSunday());
  }, []);

  // Sort function to be reused
  const sortMembers = (a: Member, b: Member) => {
    // Priority: Leader -> Alphabetical

    // 1. Leader Check
    const roleA = (a.role || '').toString().toUpperCase().trim();
    const roleB = (b.role || '').toString().toUpperCase().trim();

    const isALeader = roleA === 'LEADER' || roleA === '리더';
    const isBLeader = roleB === 'LEADER' || roleB === '리더';

    if (isALeader && !isBLeader) return -1;
    if (!isALeader && isBLeader) return 1;

    // 2. Alphabetical Check
    const nameA = a.name.replace(/\*/g, '').trim();
    const nameB = b.name.replace(/\*/g, '').trim();

    return nameA.localeCompare(nameB);
  };

  // Filter members based on selected group (for dropdown)
  const membersInGroup = useMemo(() => {
    if (!selectedGroup) return [];
    return members
      .filter(m => m.group === selectedGroup)
      .sort(sortMembers);
  }, [members, selectedGroup]);

  // View 1: By Date - Group by Small Group/Wool directly (Flattened)
  const recordsByDate = useMemo<Record<string, { member: Member; record: PrayerRecord }[]>>(() => {
    const records = prayerRecords.filter(r => r.date === selectedDate);
    const groups: Record<string, { member: Member; record: PrayerRecord }[]> = {};

    members.forEach(member => {
       const record = records.find(r => r.memberId === member.id);
       if (!groups[member.group]) groups[member.group] = [];

       // UPDATED: Only show if there is an actual record for this date.
       // Do NOT show just because there is a member specialNote (memo)
       if (record) {
         groups[member.group].push({ member, record });
       }
    });
    return groups;
  }, [selectedDate, prayerRecords, members]);

  // Check if there are any records to display for the Empty State
  const hasAnyRecords = useMemo(() => {
    return Object.values(recordsByDate).some(items => items.length > 0);
  }, [recordsByDate]);

  // View 2: By Member - Search Query OR Single Member OR All in Group
  const memberHistoryData = useMemo<{ member: Member; records: PrayerRecord[] }[] | null>(() => {
    let targetMembers: Member[] = [];

    // Priority 1: Search Query
    if (searchQuery.trim()) {
       const query = searchQuery.toLowerCase().trim();
       targetMembers = members.filter(m => m.name.toLowerCase().includes(query));
    }
    // Priority 2: Specific Member Selected via Dropdown
    else if (selectedMemberId) {
      const m = members.find(m => m.id === selectedMemberId);
      if (m) targetMembers = [m];
    } 
    // Priority 3: Group Selected
    else if (selectedGroup) {
      targetMembers = members
        .filter(m => m.group === selectedGroup)
        .sort(sortMembers);
    } 
    else {
      return null;
    }

    if (targetMembers.length === 0) return [];

    return targetMembers.map(member => {
       const myRecords = prayerRecords
        .filter(r => r.memberId === member.id)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
       return { member, records: myRecords };
    });
  }, [searchQuery, selectedMemberId, selectedGroup, members, prayerRecords]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setSearchQuery(val);
    if (val) {
      setSelectedGroup('');
      setSelectedMemberId('');
    }
  };

  const handleGroupChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedGroup(e.target.value);
    setSelectedMemberId(''); 
    setSearchQuery('');
  };

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
    setSearchQuery(''); 
  };

  return (
    <div className="space-y-6">
       <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">기도 제목 및 특이사항</h2>
          <p className="text-slate-500">
            {viewMode === 'date' 
              ? '매주 입력되는 기도제목과 특이사항을 소그룹/울별로 확인합니다.' 
              : '각 성도님의 기도제목 및 특이사항 히스토리를 확인합니다.'}
          </p>
        </div>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button
             onClick={() => setViewMode('date')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'date' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <Calendar size={16} className="mr-2" /> 날짜별 보기
           </button>
           <button
             onClick={() => setViewMode('member')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-all ${
               viewMode === 'member' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'
             }`}
           >
             <User size={16} className="mr-2" /> 멤버별 보기
           </button>
        </div>
      </header>

      {viewMode === 'date' && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <label className="font-bold text-slate-700">날짜 선택:</label>
          <select
            className="border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
          >
            {SUNDAYS_2026.slice().reverse().map(d => ( 
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      )}

      {viewMode === 'member' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4 md:space-y-0 md:flex md:gap-6 items-end">
          <div className="flex-1 w-full">
            <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center text-indigo-700">
              <Search size={14} className="mr-1" /> 이름 직접 검색 (추천)
            </label>
            <div className="relative">
              <input 
                type="text" 
                className="w-full border border-indigo-200 rounded-lg pl-10 pr-4 py-2.5 text-sm focus:ring-indigo-500 focus:border-indigo-500 bg-indigo-50/30"
                placeholder="이름을 입력하세요 (예: 김철수)"
                value={searchQuery}
                onChange={handleSearchChange}
              />
              <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-indigo-400">
                <Search size={18} />
              </div>
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-400 hover:text-slate-600"
                >
                  <X size={16} />
                </button>
              )}
            </div>
          </div>

          <div className="hidden md:flex items-center justify-center pb-3 px-2 text-slate-300 font-bold text-sm">OR</div>
          <div className="md:hidden text-center text-xs text-slate-400 my-2">- 또는 소그룹으로 찾기 -</div>

          <div className="flex-1 w-full flex gap-3">
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">소그룹 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500"
                 value={selectedGroup}
                 onChange={handleGroupChange}
               >
                 <option value="">선택 안 함</option>
                 {availableGroups.map(g => (
                   <option key={g} value={g}>{g}</option>
                 ))}
               </select>
            </div>
            <div className="flex-1">
               <label className="block text-xs font-bold text-slate-500 mb-2">멤버 선택</label>
               <select
                 className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-400"
                 value={selectedMemberId}
                 onChange={handleMemberChange}
                 disabled={!selectedGroup}
               >
                 <option value="">전체 보기</option>
                 {membersInGroup.map(m => (
                   <option key={m.id} value={m.id}>{m.name}</option>
                 ))}
               </select>
            </div>
          </div>
        </div>
      )}

      {viewMode === 'date' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Object.entries(recordsByDate).map(([groupName, items]) => {
            const groupItems = items;
            if (groupItems.length === 0) return null;
            return (
               <div key={groupName} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                  <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                    <span className="w-2 h-2 bg-indigo-500 rounded-full mr-2"></span>
                    {groupName}
                  </h3>

                  <div className="space-y-4">
                    {groupItems.map(({ member, record }) => (
                      <div key={member.id} className="relative pl-4 border-l-2 border-slate-100 hover:border-indigo-300 transition-colors">
                        <div className="flex items-baseline justify-between">
                          <h4 className="font-semibold text-slate-800">{member.name}</h4>
                          {member.specialNotes && (
                            <span className="flex items-center text-xs text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-100 max-w-[50%] truncate">
                              <AlertCircle size={10} className="mr-1" />
                              {member.specialNotes}
                            </span>
                          )}
                        </div>

                        {/* Always show content since we filtered by record existence */}
                         <>
                           {record.content && (
                             <div className="mt-2 text-sm text-slate-600 flex items-start">
                               <Quote size={14} className="text-slate-300 mr-2 mt-1 flex-shrink-0" />
                               <p>{record.content}</p>
                             </div>
                           )}
                           {record.note && (
                             <div className="mt-2 text-sm text-slate-700 flex items-start bg-yellow-50 p-2 rounded border border-yellow-100">
                               <FileText size={14} className="text-yellow-600 mr-2 mt-0.5 flex-shrink-0" />
                               <p>{record.note}</p>
                             </div>
                           )}
                         </>
                      </div>
                    ))}
                  </div>
              </div>
            );
          })}
          {!hasAnyRecords && (
             <div className="col-span-full text-center py-12 text-slate-400">
               해당 날짜에 등록된 내용이 없습니다.
             </div>
          )}
        </div>
      )}

      {/* ... Member View ... */}
      {viewMode === 'member' && (
         <div className="space-y-6">
            {!memberHistoryData ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[400px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <Search size={48} className="mb-4 opacity-10" />
                  <p>위에서 이름을 검색하거나, 소그룹을 선택하여 기록을 확인하세요.</p>
               </div>
            ) : memberHistoryData.length === 0 ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 min-h-[300px] flex flex-col items-center justify-center p-12 text-slate-400">
                  <AlertCircle size={48} className="mb-4 opacity-10" />
                  <p>검색 결과가 없습니다.</p>
